  app.post('/api/auth/invitations/complete', authLimiter, async (req: any, res: Response) => {
    try {
      const validation = completeRegistrationSchema.safeParse(req.body);
      if (!validation.success) {
        return res.status(400).json({ 
          message: "Invalid request",
          errors: validation.error.errors 
        });
      }
      
      const { token, password } = validation.data;
      const result = await passwordAuthService.completeRegistration(token, password);
      
      if (!result.success) {
        return res.status(400).json({ message: result.error || "Failed to complete registration" });
      }
      
      // Auto-login after registration
      if (result.user) {
        req.session.userId = result.user.id;
        req.session.authProvider = 'password';
        
        // Auto-enroll beta testers in all public classes
        if (result.user.isBetaTester) {
          try {
            const publicClasses = await (storage as any).getPublicCatalogueClasses();
            let enrolledCount = 0;
            for (const cls of publicClasses) {
              const alreadyEnrolled = await storage.isStudentEnrolled(cls.id, result.user.id);
              if (!alreadyEnrolled) {
                await storage.enrollStudent(cls.id, result.user.id);
                enrolledCount++;
              }
            }
            console.log(`[Beta Tester] Auto-enrolled ${result.user.email} in ${enrolledCount} public classes`);
          } catch (enrollError) {
            console.error('[Beta Tester] Failed to auto-enroll:', enrollError);
          }
        }
      }
      
      res.json({ success: true, user: result.user });
    } catch (error) {
      console.error("Complete registration error:", error);
      res.status(500).json({ message: "Failed to complete registration" });
    }
  });
  
