  // ===== Mastery Stats =====

  app.get("/api/mastery-stats", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const { language } = req.query;

      const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

      const masteredVocabRows = await getSharedDb()
        .select({ targetText: userReviewItems.targetText, itemType: userReviewItems.itemType, createdAt: userReviewItems.createdAt })
        .from(userReviewItems)
        .where(
          and(
            eq(userReviewItems.userId, userId),
            eq(userReviewItems.mastered, true),
            language ? eq(userReviewItems.language, language as string) : sql`true`
          )
        )
        .orderBy(desc(userReviewItems.createdAt));

      const masteredDrillRows = await getSharedDb()
        .select({
          masteredAt: userDrillProgress.masteredAt,
          lessonName: curriculumLessons.name,
        })
        .from(userDrillProgress)
        .leftJoin(curriculumDrillItems, eq(userDrillProgress.drillItemId, curriculumDrillItems.id))
        .leftJoin(curriculumLessons, eq(curriculumDrillItems.lessonId, curriculumLessons.id))
        .where(and(eq(userDrillProgress.userId, userId), eq(userDrillProgress.mastered, true)))
        .orderBy(desc(userDrillProgress.masteredAt));

      const totalMasteredVocab = masteredVocabRows.length;
      const totalMasteredDrills = masteredDrillRows.length;
      const totalMastered = totalMasteredVocab + totalMasteredDrills;

      const recentlyMasteredVocab = masteredVocabRows
        .filter(r => new Date(r.createdAt) >= sevenDaysAgo)
        .slice(0, 5)
        .map(r => ({ word: r.targetText, type: r.itemType as string }));

      const recentlyMasteredDrills = masteredDrillRows
        .filter(r => r.masteredAt && new Date(r.masteredAt) >= sevenDaysAgo)
        .slice(0, 3)
        .map(r => ({ word: r.lessonName ?? 'Drill', type: 'drill' }));

      const recentlyMastered = [...recentlyMasteredVocab, ...recentlyMasteredDrills].slice(0, 6);

      const MILESTONES = [
        { count: 10, label: 'First 10' },
        { count: 25, label: '25 Words' },
        { count: 50, label: '50 Words' },
        { count: 100, label: 'Century' },
        { count: 250, label: '250 Words' },
        { count: 500, label: '500 Words' },
      ];

      const milestones = MILESTONES.map(m => ({ ...m, achieved: totalMastered >= m.count }));
      const nextMilestone = MILESTONES.find(m => m.count > totalMastered)?.count ?? null;

      res.json({ totalMasteredVocab, totalMasteredDrills, totalMastered, recentlyMastered, milestones, nextMilestone });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // ===== Vocabulary Export =====
  
  // Export vocabulary in CSV or Anki format
  app.get("/api/vocabulary/export", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const { language, format = 'csv' } = req.query;
      
      if (!language) {
        return res.status(400).json({ error: "Language parameter is required" });
      }
      
      if (!['csv', 'anki'].includes(format as string)) {
        return res.status(400).json({ error: "Format must be 'csv' or 'anki'" });
      }
      
      const words = await storage.getVocabularyWords(language as string, userId);
      
      if (format === 'anki') {
        const ankiData = words.map(w => 
          `${w.word}\t${w.translation}\t${w.example}\t${w.pronunciation}\t${w.difficulty}\t${w.actflLevel || ''}`
        ).join('\n');
        
        res.setHeader('Content-Type', 'text/tab-separated-values');
        res.setHeader('Content-Disposition', `attachment; filename="vocabulary_${language}_anki.txt"`);
        return res.send(ankiData);
      }
      
      const csvHeader = 'Word,Translation,Example,Pronunciation,Difficulty,ACTFL Level,Review Count,Correct Count,Created\n';
      const csvData = words.map(w => {
        const createdDate = w.createdAt ? new Date(w.createdAt).toISOString().split('T')[0] : '';
        return `"${(w.word || '').replace(/"/g, '""')}","${(w.translation || '').replace(/"/g, '""')}","${(w.example || '').replace(/"/g, '""')}","${(w.pronunciation || '').replace(/"/g, '""')}","${w.difficulty || ''}","${w.actflLevel || ''}","${(w as any).reviewCount || 0}","${w.correctCount || 0}","${createdDate}"`;
      }).join('\n');
      
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="vocabulary_${language}.csv"`);
      return res.send(csvHeader + csvData);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

