  // Pronunciation Scores - Analyze and save
  app.post("/api/pronunciation-scores/analyze", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const { messageId, conversationId, transcribedText } = req.body;
      
      if (!messageId || !conversationId || !transcribedText) {
        return res.status(400).json({ error: "messageId, conversationId, and transcribedText are required" });
      }

      // Get conversation to determine language and difficulty - verify ownership
      const conversation = await storage.getConversation(conversationId, userId);
      if (!conversation) {
        return res.status(404).json({ message: "Conversation not found" });
      }

      // Import pronunciation analysis
      const { analyzePronunciation } = await import("./pronunciation-analysis");
      
      // Analyze pronunciation
      // analyzePronunciation throws on missing key (ConfigurationError) and on
      // API failures (401 expired, 429 rate-limit, network errors).  We catch
      // those here and return a structured { error, reason } body so the client
      // can show a visible notice rather than treating a missing result as success.
      //
      // Expected error shape on HTTP 500:
      //   { error: 'pronunciation_unavailable', reason: '<human-readable cause>' }
      //
      // Possible reason values (non-exhaustive):
      //   'OpenAI API key not configured'
      //   'OpenAI API key is invalid or expired'
      //   'OpenAI rate limit reached; try again shortly'
      //   '<raw error message>'           ← for unexpected failures
      let analysis;
      try {
        analysis = await analyzePronunciation(
          transcribedText,
          conversation.language,
          conversation.difficulty
        );
      } catch (apiError: any) {
        console.error("[pronunciation-analysis] API call failed:", apiError);
        const reason = mapApiErrorToReason(apiError);
        return res.status(500).json({ error: 'pronunciation_unavailable', reason });
      }

      // Save the score
      const score = await storage.createPronunciationScore({
        messageId,
        conversationId,
        transcribedText,
        targetPhrase: null,
        score: analysis.score,
        feedback: analysis.feedback,
        phoneticIssues: analysis.phoneticIssues.length > 0 ? analysis.phoneticIssues : null,
      });

      // Return full analysis to client
      res.status(201).json({
        ...score,
        strengths: analysis.strengths,
      });
    } catch (error: any) {
      console.error("Error analyzing pronunciation:", error);
      res.status(500).json({ error: 'pronunciation_unavailable', reason: error?.message || 'Pronunciation analysis failed' });
    }
  });

