  // ========== INSTITUTIONAL FEATURES ==========

  // ===== Teacher Classes =====
  
  // Create a new class (teachers only)
  app.post("/api/teacher/classes", mutationLimiter, isAuthenticated, async (req: any, res: Response) => {
    try {
      const teacherId = getRequestUserId(req)!;
      const user = await storage.getUser(teacherId);
      
      if (!hasTeacherAccess(user?.role)) {
        return res.status(403).json({ error: "Only teachers can create classes" });
      }

      const { name, description, language, curriculumPathId, subjectSyllabusId, isAcademicClass } = req.body;
      
      if (!name) {
        return res.status(400).json({ error: 'Name is required' });
      }
      if (!language && !isAcademicClass) {
        return res.status(400).json({ error: 'Language is required for language classes' });
      }

      // Generate 6-digit join code
      const joinCode = Math.random().toString(36).substring(2, 8).toUpperCase();

      // Create class with isPublicCatalogue=false initially; will be updated after TOC seeding
      const teacherClass = await storage.createTeacherClass({
        teacherId,
        name,
        description,
        language: language || subjectSyllabusId || 'academic',
        curriculumPathId,
        joinCode,
        subjectSyllabusId: subjectSyllabusId || null,
        isAcademicClass: isAcademicClass || false,
        isPublicCatalogue: false,
      });

      // If a curriculum template was selected, clone it to the class
      if (curriculumPathId) {
        try {
          await storage.cloneCurriculumToClass(teacherClass.id, curriculumPathId);
        } catch (cloneError) {
          console.error('Error cloning curriculum to class:', cloneError);
        }
      }

      // For academic classes: seed TOC if not already populated, then mark public
      if (isAcademicClass && subjectSyllabusId) {
        try {
          const [existing] = await db
            .select({ units: subjectSyllabi.units })
            .from(subjectSyllabi)
            .where(eq(subjectSyllabi.subject, subjectSyllabusId))
            .limit(1);

          let hasContent = Array.isArray(existing?.units) && existing.units.length > 0;

          if (!hasContent) {
            const toc = getTOCForSubject(subjectSyllabusId);
            if (toc && toc.length > 0) {
              await db
                .update(subjectSyllabi)
                .set({ units: toc })
                .where(eq(subjectSyllabi.subject, subjectSyllabusId));
              hasContent = true;
              console.log(`[ClassCreation] Seeded TOC for subject: ${subjectSyllabusId} (${toc.length} units)`);
            } else {
              console.log(`[ClassCreation] No TOC data found for subject: ${subjectSyllabusId}`);
            }
          } else {
            hasContent = true;
            console.log(`[ClassCreation] TOC already seeded for subject: ${subjectSyllabusId}`);
          }

          if (hasContent) {
            await storage.updateTeacherClass(teacherClass.id, { isPublicCatalogue: true });
            teacherClass.isPublicCatalogue = true;
          }
        } catch (seedError) {
          console.error(`[ClassCreation] TOC seeding error for ${subjectSyllabusId}:`, seedError);
        }
      }

      res.json(teacherClass);
    } catch (error: any) {
      console.error('Error creating teacher class:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Clone an existing class (teachers only)
  app.post("/api/teacher/classes/:classId/clone", mutationLimiter, isAuthenticated, async (req: any, res: Response) => {
    try {
      const teacherId = getRequestUserId(req)!;
      const { classId } = req.params;
      const { name, description } = req.body;
      const user = await storage.getUser(teacherId);
      
      if (!hasTeacherAccess(user?.role)) {
        return res.status(403).json({ error: "Only teachers can clone classes" });
      }

      // Get the original class
      const originalClass = await storage.getTeacherClass(classId);
      if (!originalClass) {
        return res.status(404).json({ error: "Class not found" });
      }

      // Verify ownership (teachers can only clone their own classes, admins can clone any)
      if (originalClass.teacherId !== teacherId && user?.role !== 'admin') {
        return res.status(403).json({ error: "You can only clone your own classes" });
      }

      // Generate new join code
      const joinCode = Math.random().toString(36).substring(2, 8).toUpperCase();

      // Create new class with same settings
      const clonedClass = await storage.createTeacherClass({
        teacherId,
        name: name || `${originalClass.name} (Copy)`,
        description: description || originalClass.description,
        language: originalClass.language,
        curriculumPathId: originalClass.curriculumPathId,
        joinCode,
      });

      // Clone curriculum from original class if it has one
      if (originalClass.curriculumPathId) {
        try {
          await storage.cloneCurriculumToClass(clonedClass.id, originalClass.curriculumPathId);
        } catch (cloneError) {
          console.error('Error cloning curriculum to cloned class:', cloneError);
        }
      }

      res.json(clonedClass);
    } catch (error: any) {
      console.error('Error cloning teacher class:', error);
      res.status(500).json({ error: error.message });
    }
  });

