  // Get specific public class with syllabus content
  app.get("/api/classes/public/:id", async (req: any, res: Response) => {
    try {
      const { id } = req.params;
      const allClasses = await storage.getAllActiveClasses();
      const cls = allClasses.find(c => c.id === id && c.isPublicCatalogue && c.isActive);

      if (!cls) {
        return res.status(404).json({ message: "Class not found" });
      }

      const classTypesData = await storage.getActiveClassTypes();
      const ct = cls.classTypeId ? classTypesData.find(type => type.id === cls.classTypeId) : null;

      // Fetch syllabus if class has a curriculum path
      let syllabus = null;
      if (cls.curriculumPathId) {
        const units = await getSharedDb().select().from(curriculumUnits).where(eq(curriculumUnits.curriculumPathId, cls.curriculumPathId)).orderBy(curriculumUnits.orderIndex);
        
        const unitsWithLessons = await Promise.all(units.map(async (unit) => {
          const lessons = await getSharedDb().select().from(curriculumLessons).where(eq(curriculumLessons.curriculumUnitId, unit.id)).orderBy(curriculumLessons.orderIndex);
          
          // Enrich lessons with drill information if applicable
          const enrichedLessons = await Promise.all(lessons.map(async (lesson) => {
            let drillCount = 0;
            let drillType = null;
            if (lesson.lessonType === 'drill') {
              const drillItems = await getSharedDb().select().from(curriculumDrillItems).where(eq(curriculumDrillItems.lessonId, lesson.id));
              drillCount = drillItems.length;
              if (drillItems.length > 0) {
                // Determine the predominant drill type for display
                const types = drillItems.map(d => d.itemType); // Correct column name is itemType
                drillType = types[0]; // Simplest approach: show the first one's type
              }
            }
            return { ...lesson, drillCount, drillType };
          }));
          
          return { ...unit, lessons: enrichedLessons };
        }));

        syllabus = {
          pathId: cls.curriculumPathId,
          units: unitsWithLessons
        };
      }

      res.json({
        id: cls.id,
        name: cls.name,
        description: cls.description,
        language: cls.language,
        classTypeId: cls.classTypeId,
        classType: ct ? { id: ct.id, name: ct.name, slug: ct.slug, icon: ct.icon } : null,
        isFeatured: cls.isFeatured,
        featuredOrder: cls.featuredOrder,
        classLevel: cls.classLevel,
        targetActflLevel: cls.targetActflLevel,
        expectedActflMin: cls.expectedActflMin,
        syllabus
      });
    } catch (error: any) {
      console.error("Error fetching class syllabus:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Browse class catalogue - returns ONLY public classes marked with isPublicCatalogue=true
  // SECURITY: Only returns public metadata (id, name, description, language) - NO join codes
  // SECURITY: Only classes explicitly marked as public are visible - prevents institutional class leakage
  app.get("/api/classes/catalogue", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { search, language, classType } = req.query;
      const studentId = req.session?.userId || req.user?.claims?.sub;
      
      // Get all active classes
      const allClasses = await storage.getAllActiveClasses();
      
      // Get all class types for mapping
      const classTypesData = await storage.getActiveClassTypes();
      const classTypeMap = new Map(classTypesData.map(ct => [ct.id, ct]));
      
      // Get student's current enrollments to flag already-enrolled classes
      const enrollments = await storage.getStudentEnrollments(studentId);
      const enrolledClassIds = new Set(enrollments.map(e => e.classId));
      
      // SECURITY: Only show classes explicitly marked as public catalogue
      let filteredClasses = allClasses.filter(cls => {
        // CRITICAL: Must be explicitly marked as public catalogue
        if (!cls.isPublicCatalogue) return false;
        // Must be active
        if (!cls.isActive) return false;
        return true;
      });
      
      // Apply search filter if provided
      if (search && typeof search === 'string') {
        const searchLower = search.toLowerCase();
        filteredClasses = filteredClasses.filter(cls => 
          cls.name.toLowerCase().includes(searchLower) ||
          (cls.description && cls.description.toLowerCase().includes(searchLower)) ||
          cls.language.toLowerCase().includes(searchLower)
        );
      }
      
      // Apply language filter if provided
      if (language && typeof language === 'string' && language !== 'all') {
        filteredClasses = filteredClasses.filter(cls => 
          cls.language.toLowerCase() === language.toLowerCase()
        );
      }
      
      // Apply class type filter if provided
      if (classType && typeof classType === 'string' && classType !== 'all') {
        filteredClasses = filteredClasses.filter(cls => {
          if (!cls.classTypeId) return false;
          const ct = classTypeMap.get(cls.classTypeId);
          return ct && ct.slug === classType;
        });
      }
      
      // SECURITY: Return only public metadata - strip sensitive fields like joinCode
      // Include isEnrolled flag to show which classes user is already in
      const sanitizedClasses = filteredClasses.map(cls => {
        const ct = cls.classTypeId ? classTypeMap.get(cls.classTypeId) : null;
        return {
          id: cls.id,
          name: cls.name,
          description: cls.description,
          language: cls.language,
          isActive: cls.isActive,
          isEnrolled: enrolledClassIds.has(cls.id),
          targetActflLevel: cls.targetActflLevel,
          expectedActflMin: cls.expectedActflMin,
          classLevel: cls.classLevel,
          classType: ct ? {
            id: ct.id,
            name: ct.name,
            slug: ct.slug,
            icon: ct.icon,
          } : null,
        };
      });
      
      // Sort: alphabetically by name
      sanitizedClasses.sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
      
      res.json(sanitizedClasses);
    } catch (error: any) {
      console.error('Error fetching class catalogue:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Self-enroll in a catalogue class by ID (for public classes only)
  // SECURITY: Only allows enrollment in classes marked with isPublicCatalogue=true
  app.post("/api/classes/catalogue/:classId/enroll", isAuthenticated, async (req: any, res: Response) => {
    try {
      const studentId = req.session?.userId || req.user?.claims?.sub;
      const { classId } = req.params;
      
      // Get the class
      const cls = await storage.getTeacherClass(classId);
      if (!cls || !cls.isActive) {
        return res.status(404).json({ error: "Class not found" });
      }
      
      // SECURITY: Only allow self-enrollment in public catalogue classes
      if (!cls.isPublicCatalogue) {
        return res.status(403).json({ error: "This class requires a join code from your teacher" });
      }
      
      // Check if already enrolled
      const existingEnrollments = await storage.getStudentEnrollments(studentId);
      if (existingEnrollments.some(e => e.classId === classId)) {
        return res.status(400).json({ error: "You are already enrolled in this class" });
      }
      
      // Create enrollment with default allocation
      const enrollment = await (storage as any).createClassEnrollment({
        classId,
        studentId,
        isActive: true,
        allocatedSeconds: 432000, // 120 hours default
        usedSeconds: 0,
        paceStatus: 'on_track',
      });
      
      res.json({ 
        success: true, 
        enrollment,
        class: {
          id: cls.id,
          name: cls.name,
          language: cls.language,
          description: cls.description,
        }
      });
    } catch (error: any) {
      console.error('Error enrolling in catalogue class:', error);
      res.status(500).json({ error: error.message });
    }
  });

