  // Get ACTFL analysis for a curriculum path
  app.get("/api/curriculum/paths/:pathId/actfl-analysis", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { pathId } = req.params;
      const path = await storage.getCurriculumPath(pathId);
      
      if (!path) {
        return res.status(404).json({ error: "Curriculum path not found" });
      }

      const units = await storage.getCurriculumUnits(pathId);
      
      // Get all lessons and count by ACTFL level
      const lessonsByLevel: Record<string, number> = {};
      let totalLessons = 0;
      const canDoCategories = {
        interpersonal: 0,
        interpretive: 0,
        presentational: 0,
      };

      for (const unit of units) {
        const lessons = await storage.getCurriculumLessons(unit.id);
        totalLessons += lessons.length;
        
        for (const lesson of lessons) {
          const level = lesson.actflLevel || unit.actflLevel || path.startLevel;
          lessonsByLevel[level] = (lessonsByLevel[level] || 0) + 1;
          
          // Count lesson types for Can-Do categories
          if (lesson.lessonType === 'conversation') {
            canDoCategories.interpersonal++;
            canDoCategories.presentational++;
          } else if (lesson.lessonType === 'vocabulary') {
            canDoCategories.interpretive++;
          } else if (lesson.lessonType === 'grammar') {
            canDoCategories.presentational++;
          } else if (lesson.lessonType === 'cultural_exploration') {
            canDoCategories.interpretive++;
            canDoCategories.interpersonal++;
          }
        }
      }

      // Estimate Can-Do statements covered based on lesson coverage
      const estimatedStatementsCovered = Math.round(
        (canDoCategories.interpersonal + canDoCategories.interpretive + canDoCategories.presentational) * 0.4
      );

      res.json({
        levelRange: {
          start: path.startLevel,
          end: path.endLevel,
        },
        lessonsByLevel,
        totalLessons,
        totalUnits: units.length,
        canDoCategories,
        estimatedStatementsCovered,
      });
    } catch (error: any) {
      console.error('Error fetching curriculum ACTFL analysis:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // ===== Interactive Textbook API =====
  // Get full textbook structure for a language (chapters, sections, progress)
  app.get("/api/textbook/:language", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const { language } = req.params;
      
      // Normalize language to match database format
      const normalizedLanguage = language.toLowerCase().trim();
      
      console.log('[Textbook API] Fetching for language:', normalizedLanguage, 'userId:', userId);
      
      // Get curriculum paths for this language
      const paths = await storage.getCurriculumPaths(normalizedLanguage);
      
      console.log('[Textbook API] Found paths:', paths.length, paths.map(p => p.name));
      
      // Select curriculum path based on student's current ACTFL level
      const userProgress = await storage.getOrCreateUserProgress(normalizedLanguage, userId);
      const actflLevel = userProgress.currentActflLevel || 'novice_low';
      
      // Allow explicit path override via query param (for manual path switching)
      const requestedPathId = req.query.pathId as string | undefined;
      
      let primaryPath = requestedPathId 
        ? paths.find(p => p.id === requestedPathId)
        : undefined;
      
      if (!primaryPath) {
        // Map: find the path whose start_level matches the student's current ACTFL level
        const ACTFL_ORDER = ['novice_low', 'novice_mid', 'novice_high', 'intermediate_low', 'intermediate_mid', 'intermediate_high', 'advanced_low', 'advanced_mid', 'advanced_high'];
        const studentLevelIndex = ACTFL_ORDER.indexOf(actflLevel);
        
        primaryPath = paths.find(p => p.startLevel === actflLevel);
        
        if (!primaryPath && studentLevelIndex >= 0) {
          primaryPath = paths.find(p => {
            const startIdx = ACTFL_ORDER.indexOf(p.startLevel || '');
            const endIdx = ACTFL_ORDER.indexOf(p.endLevel || '');
            return startIdx >= 0 && endIdx >= 0 && studentLevelIndex >= startIdx && studentLevelIndex <= endIdx;
          });
        }
        
        if (!primaryPath) {
          primaryPath = paths.find(p => 
            p.name.toLowerCase().includes('1') || 
            p.startLevel?.toLowerCase().includes('novice_low')
          ) || paths[0];
        }
      }
      
      console.log('[Textbook API] Student ACTFL level:', actflLevel, '→ Selected path:', primaryPath?.name || 'none');
      
      // Also return all available paths so the frontend can offer path switching
      const allPaths = paths.map(p => ({
        id: p.id,
        name: p.name,
        startLevel: p.startLevel,
        endLevel: p.endLevel,
      }));
      
      if (!primaryPath) {
        return res.json({
          language: normalizedLanguage,
          chapters: [],
          message: "No curriculum available for this language yet"
        });
      }
      
      // Get all units (chapters) for this path
      const units = await storage.getCurriculumUnits(primaryPath.id);
      
      // Pre-load all scenario topic data once for reverse bridge (lesson → scenario)
      const allScenarioTopics = await getSharedDb()
        .select({ slug: scenarios.slug, title: scenarios.title, curriculumTopics: scenarios.curriculumTopics })
        .from(scenarios)
        .where(isNotNull(scenarios.curriculumTopics));
      
      console.log('[Textbook API] Found units:', units.length);
      
      // Build chapter structure with lessons (sections)
      // For performance, we skip individual drill progress checks on the overview
      // and only load detailed progress when a chapter is opened
      const chapters = await Promise.all(units.map(async (unit, index) => {
        const lessons = await storage.getCurriculumLessons(unit.id);
        
        // Build sections with drill data for study guides
        const sections = await Promise.all(lessons.map(async (lesson) => {
          // Load drills for study guide content
          const drillItems = await storage.getDrillItems(lesson.id);
          
          return {
            id: lesson.id,
            name: lesson.name.replace(/^(Lesson|Section|Unit)\s+\d+:\s*/i, ''),
            description: lesson.description || '',
            lessonType: lesson.lessonType || 'lesson',
            estimatedMinutes: lesson.estimatedMinutes || 10,
            progress: 0, // Progress computed on demand in chapter detail view
            isComplete: false,
            hasDrills: drillItems.length > 0,
            drillCount: drillItems.length,
            objectives: lesson.objectives || [],
            conversationTopic: lesson.conversationTopic,
            imageUrl: lesson.imageUrl || null,
            relatedScenario: (() => {
              const lt = new Set(lesson.requiredTopics || []);
              if (lt.size === 0) return null;
              const scored = allScenarioTopics
                .map(s => ({ slug: s.slug, title: s.title, score: (s.curriculumTopics || []).filter((t) => lt.has(t)).length }))
                .filter(s => s.score > 0)
                .sort((a, b) => b.score - a.score);
              return scored[0] ? { slug: scored[0].slug, title: scored[0].title } : null;
            })(),
            drills: drillItems.slice(0, 21).map(item => ({
              id: item.id,
              itemType: item.itemType,
              prompt: item.prompt,
              targetText: item.targetText,
              difficulty: item.difficulty || 1,
              mastered: false,
              attempts: 0,
            })),
          };
        }));
        
        // Chapter is locked if previous chapter is not at least 50% complete (except first)
        const isLocked = index > 0; // Updated below based on actual progress
        
        return {
          id: unit.id,
          number: index + 1,
          title: unit.name.replace(/^(Unit|Chapter)\s+\d+:\s*/i, ''),
          description: unit.description || '',
          progress: 0, // Overview shows 0 for simplicity; detailed view shows actual
          isLocked,
          sectionsCount: sections.length,
          completedSections: 0,
          sections,
          culturalTheme: unit.culturalTheme,
          actflLevel: unit.actflLevel,
          chapterType: unit.chapterType || null,
        };
      }));
      
      console.log('[Textbook API] Built chapters:', chapters.length);
      
      // For simplicity in the textbook overview, keep all chapters unlocked
      // (progressive unlocking can be added later with user progress tracking)
      for (let i = 1; i < chapters.length; i++) {
        chapters[i].isLocked = false;
      }
      
      res.json({
        language: normalizedLanguage,
        curriculumPath: {
          id: primaryPath.id,
          name: primaryPath.name,
          description: primaryPath.description,
          startLevel: primaryPath.startLevel,
          endLevel: primaryPath.endLevel,
        },
        allPaths,
        studentActflLevel: actflLevel,
        chapters,
        totalChapters: chapters.length,
        completedChapters: chapters.filter(c => c.progress === 100).length,
      });
    } catch (error: any) {
      console.error('Error fetching textbook data:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get specific chapter content with full section details
  app.get("/api/textbook/:language/chapter/:chapterId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const { chapterId } = req.params;
      
      const unit = await storage.getCurriculumUnit(chapterId);
      if (!unit) {
        return res.status(404).json({ error: "Chapter not found" });
      }
      
      const lessons = await storage.getCurriculumLessons(chapterId);
      
      const lessonIds = lessons.map(l => l.id);
      
      // Pre-load scenario topics once for reverse bridge
      const allScenarioTopicsDetail = await getSharedDb()
        .select({ slug: scenarios.slug, title: scenarios.title, curriculumTopics: scenarios.curriculumTopics })
        .from(scenarios)
        .where(isNotNull(scenarios.curriculumTopics));

      // Batch-fetch textbook read status and Daniela-covered status for all lessons
      const [textbookReadRecords, danielaCoveredRecords] = await Promise.all([
        lessonIds.length > 0
          ? getUserDb().select({ lessonId: textbookSectionProgress.lessonId, completed: textbookSectionProgress.completed })
              .from(textbookSectionProgress)
              .where(and(eq(textbookSectionProgress.userId, userId), inArray(textbookSectionProgress.lessonId, lessonIds)))
          : Promise.resolve([]),
        lessonIds.length > 0
          ? getUserDb().select({ lessonId: studentLessonProgress.lessonId, status: studentLessonProgress.status })
              .from(studentLessonProgress)
              .where(and(eq(studentLessonProgress.studentId, userId), inArray(studentLessonProgress.lessonId, lessonIds)))
          : Promise.resolve([]),
      ]);

      const textbookReadMap = new Map(textbookReadRecords.map(r => [r.lessonId, r.completed]));
      const danielaCoveredMap = new Map(danielaCoveredRecords.map(r => [r.lessonId, r.status]));

      const sections = await Promise.all(lessons.map(async (lesson) => {
        const drillItems = await storage.getDrillItems(lesson.id);
        
        // Get progress for each drill
        const drillsWithProgress = await Promise.all(drillItems.map(async (item) => {
          const progress = await storage.getDrillProgress(userId, item.id);
          return {
            id: item.id,
            itemType: item.itemType,
            prompt: item.prompt,
            targetText: item.targetText,
            difficulty: item.difficulty,
            mastered: (progress as any)?.masteryLevel ? (progress as any).masteryLevel >= 3 : false,
            attempts: (progress as any)?.totalAttempts || 0,
          };
        }));
        
        const completedDrills = drillsWithProgress.filter(d => d.mastered).length;
        const progressPercent = drillItems.length > 0 
          ? Math.round((completedDrills / drillItems.length) * 100)
          : 0;
        
        return {
          id: lesson.id,
          name: lesson.name.replace(/^(Lesson|Section|Unit)\s+\d+:\s*/i, ''),
          description: lesson.description,
          lessonType: lesson.lessonType,
          objectives: lesson.objectives,
          estimatedMinutes: lesson.estimatedMinutes,
          progress: progressPercent,
          isComplete: progressPercent === 100,
          drills: drillsWithProgress,
          conversationTopic: lesson.conversationTopic,
          conversationPrompt: lesson.conversationPrompt,
          relatedScenario: (() => {
            const lt = new Set(lesson.requiredTopics || []);
            if (lt.size === 0) return null;
            const scored = allScenarioTopicsDetail
              .map(s => ({ slug: s.slug, title: s.title, score: (s.curriculumTopics || []).filter((t) => lt.has(t)).length }))
              .filter(s => s.score > 0)
              .sort((a, b) => b.score - a.score);
            return scored[0] ? { slug: scored[0].slug, title: scored[0].title } : null;
          })(),
          textbookRead: textbookReadMap.get(lesson.id) === true,
          danielaCovered: danielaCoveredMap.get(lesson.id) === 'completed',
          imageUrl: lesson.imageUrl || null,
        };
      }));
      
      res.json({
        id: unit.id,
        title: unit.name.replace(/^(Unit|Chapter)\s+\d+:\s*/i, ''),
        description: unit.description,
        culturalTheme: unit.culturalTheme,
        actflLevel: unit.actflLevel,
        chapterType: unit.chapterType || null,
        sections,
      });
    } catch (error: any) {
      console.error('Error fetching chapter:', error);
      res.status(500).json({ error: error.message });
    }
  });

