  app.get("/api/textbook/vocab-images/:lessonId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { lessonId } = req.params;
      const { language } = req.query;
      
      if (!language) {
        return res.status(400).json({ error: "Language query param is required" });
      }

      const drillItems = await storage.getDrillItems(lessonId);
      const vocabItems = drillItems
        .filter(d => d.itemType === 'listen_repeat' || d.itemType === 'translate_speak')
        .filter(d => d.targetText && d.targetText.length < 50);

      if (vocabItems.length === 0) {
        return res.json({ images: {} });
      }

      const { resolveVocabularyImage } = await import('./services/vocabulary-image-resolver');
      const { getVocabSpeakerGender } = await import('./services/vocab-image-seed-service');

      const concurrency = 3;
      const images: Record<string, { url: string; source: string; speakerGender: 'male' | 'female' }> = {};
      const romanizations: Record<string, string> = {};
      
      const { getRomanization } = await import('./services/romanization-utils');

      // Pre-compute romanizations for all vocab items
      for (const item of vocabItems) {
        const r = getRomanization(item.targetText, language as string);
        if (r) romanizations[item.id] = r;
      }

      for (let i = 0; i < vocabItems.length; i += concurrency) {
        const batch = vocabItems.slice(i, i + concurrency);
        const results = await Promise.all(
          batch.map(async (item) => {
            try {
              const result = await resolveVocabularyImage({
                word: item.targetText,
                language: language as string,
                description: item.prompt || item.targetText,
              });
              const speakerGender = getVocabSpeakerGender(item.targetText, language as string);
              return { id: item.id, url: result.imageUrl, source: result.source, speakerGender };
            } catch (err: any) {
              console.error(`[VocabImages] Failed for "${item.targetText}":`, err.message);
              return { id: item.id, url: null, source: 'error', speakerGender: 'female' as const };
            }
          })
        );
        
        for (const r of results) {
          if (r.url) {
            images[r.id] = { url: r.url, source: r.source, speakerGender: r.speakerGender };
          }
        }
      }

      res.json({ images, romanizations });
    } catch (error: any) {
      console.error('Error resolving vocab images:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Batch lookup vocab images by explicit cache key(s) — used by SentenceFrameGrid (M5).
  // GET /api/textbook/vocab-images-by-keys?keys=vocab_spanish_feliz,vocab_spanish_cansado
  app.get("/api/textbook/vocab-images-by-keys", isAuthenticated, async (req: any, res: Response) => {
    try {
      const raw = req.query.keys as string | undefined;
      if (!raw || raw.trim() === '') return res.json({ images: {} });
      const keys = raw.split(',').map((k: string) => k.trim()).filter(Boolean).slice(0, 40);
      if (keys.length === 0) return res.json({ images: {} });

      const sharedDb = getSharedDb();
      const rows = await sharedDb
        .select({ searchQuery: mediaFiles.searchQuery, url: mediaFiles.url, imageSource: mediaFiles.imageSource })
        .from(mediaFiles)
        .where(inArray(mediaFiles.searchQuery, keys));

      const images: Record<string, { url: string; source: string }> = {};
      for (const row of rows) {
        if (row.searchQuery && row.url && !images[row.searchQuery]) {
          images[row.searchQuery] = { url: row.url, source: row.imageSource ?? 'cached' };
        }
      }
      res.json({ images });
    } catch (error: any) {
      console.error('[VocabImagesByKeys]', error.message);
      res.status(500).json({ error: error.message });
    }
  });

  // ── Madrigal Book Page Scans ─────────────────────────────────────────────
  // Serves scanned page images from Object Storage.
  // Pages are stored under: public/madrigal/scans/main/page-NNN.jpg
  //                          public/madrigal/scans/appendix/page-NNN.jpg

  app.get("/api/book/page-scan/:book/:pageNumber", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { book, pageNumber } = req.params;
      if (!["main", "appendix"].includes(book)) {
        return res.status(400).json({ error: "book must be 'main' or 'appendix'" });
      }
      const n = parseInt(pageNumber, 10);
      if (isNaN(n) || n < 1 || n > 200) {
        return res.status(400).json({ error: "Invalid page number" });
      }
      const padded = String(n).padStart(3, "0");
      const { ObjectStorageService } = await import("./replit_integrations/object_storage/objectStorage");
      const svc = new ObjectStorageService();
      const file = await svc.searchPublicObject(`madrigal/scans/${book}/page-${padded}.jpg`);
      if (!file) {
        return res.status(404).json({ error: `Page ${n} scan not yet uploaded` });
      }
      await svc.downloadObject(file, res, 365 * 24 * 3600);
    } catch (err: any) {
      console.error("[MadrigalScan]", err.message);
      res.status(500).json({ error: "Failed to serve scan" });
    }
  });

  // List which pages have been uploaded (useful for admin view / progress)
  app.get("/api/book/page-scan-manifest/:book", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { book } = req.params;
      if (!["main", "appendix"].includes(book)) {
        return res.status(400).json({ error: "book must be 'main' or 'appendix'" });
      }
      const bucketName = (process.env.PUBLIC_OBJECT_SEARCH_PATHS ?? "")
        .split(",")[0].trim().replace(/^\//, "").split("/")[0];
      if (!bucketName) return res.status(500).json({ error: "Bucket not configured" });

      const { listObjects } = await import("./replit_integrations/object_storage/objectStorage");
      const keys = await listObjects(bucketName, `public/madrigal/scans/${book}/`);
      const pages = keys
        .map((name: string) => {
          const m = name.match(/page-(\d+)\.jpg$/);
          return m ? parseInt(m[1], 10) : null;
        })
        .filter(Boolean)
        .sort((a: number | null, b: number | null) => (a ?? 0) - (b ?? 0));
      res.json({ book, totalPages: pages.length, pages });
    } catch (err: any) {
      console.error("[MadrigalScanManifest]", err.message);
      res.status(500).json({ error: err.message });
    }
  });

  // ── Textbook Content Routes ───────────────────────────────────────────────

  // Fetch textbook prose content for a single lesson
  app.get('/api/textbook-content/:lessonId', isAuthenticated, async (req: any, res: Response) => {
    try {
      const { lessonId } = req.params;
      const { getUserDb } = await import('./db');
      const { sql: drizzleSql } = await import('drizzle-orm');
      const db = getUserDb();
      const row = await db.execute(drizzleSql`SELECT * FROM textbook_lesson_content WHERE lesson_id = ${lessonId} LIMIT 1`);
      if (row.rows.length === 0) return res.json({ content: null });
      res.json({ content: row.rows[0] });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // ── Micro-cycle data generator ─────────────────────────────────────────────
  // Generates NegativeForm / QuestionForm / SentenceColumns for a lesson.
  // L1: In-memory Map cache (fast, lost on restart)
  // L2: DB column micro_cycle_data (persistent, survives restarts)
  // L3: Claude generation (first-ever call per lesson × language, ~2-3s)
  // Works for all 9 supported languages — pass ?language=<lang> param.
  // GET /api/textbook/micro-cycle/:lessonId?language=spanish
  {
    const microCycleCache = new Map<string, object>();

    app.get('/api/textbook/micro-cycle/:lessonId', isAuthenticated, async (req: any, res: Response) => {
      try {
        const { lessonId } = req.params;
        const language = (req.query.language as string) || 'spanish';
        const cacheKey = `${lessonId}::${language}`;

        // L1: in-memory cache
        if (microCycleCache.has(cacheKey)) {
          return res.json({ ...microCycleCache.get(cacheKey), fromCache: true });
        }

        const { getUserDb } = await import('./db');
        const { sql: drizzleSql } = await import('drizzle-orm');
        const db = getUserDb();
        const row = await db.execute(
          drizzleSql`SELECT key_phrases_for_chat, vocabulary_list, micro_cycle_data FROM textbook_lesson_content WHERE lesson_id = ${lessonId} AND language = ${language} LIMIT 1`
        );

        // Try fallback without language filter if no row found
        let contentRow = row.rows[0];
        if (!contentRow) {
          const fallback = await db.execute(
            drizzleSql`SELECT key_phrases_for_chat, vocabulary_list, micro_cycle_data FROM textbook_lesson_content WHERE lesson_id = ${lessonId} LIMIT 1`
          );
          contentRow = fallback.rows[0];
        }

        if (!contentRow) return res.status(404).json({ error: 'No content for this lesson' });

        // L2: DB cache — return immediately if already generated
        if (contentRow.micro_cycle_data) {
          const cached = contentRow.micro_cycle_data as object;
          microCycleCache.set(cacheKey, cached);
          return res.json({ ...cached, fromCache: true });
        }

        const keyPhrases = (contentRow.key_phrases_for_chat ?? []) as Array<{ phrase: string; translation: string; context: string }>;
        const vocabList = (contentRow.vocabulary_list ?? []) as Array<{
          word: string;
          translation: string;
          gender?: string;
          partOfSpeech?: string;
          exampleSentences?: Array<{ target: string; translation: string }>;
        }>;

        if (keyPhrases.length === 0 && vocabList.length === 0) {
          return res.json({ negativeItems: [], questionItems: [], sentenceColumns: [], patternLabel: '', fromCache: false });
        }

        // L3: Claude generation
        const anthropic = new Anthropic();
        const prompt = `You are generating micro-cycle practice data for HolaHola, an AI-powered language learning app.
Language: ${language}

════════════════════════════════════════════════════════════════
HOLAHOLA PEDAGOGY — READ THIS BEFORE GENERATING ANYTHING
(This is not generic language-teaching context. It overrides every
textbook-derived instinct you have about how drills should work.)
════════════════════════════════════════════════════════════════

OUR LEARNING MODEL (from product audits, Jan–Apr 2026):
The textbook is not the learning event. It is rapid preparation for the
real learning event — a voice session with Daniela, the AI tutor.
Students absorb a pattern quickly from the textbook (scan, hear it, see it)
then go USE it in conversation. The drill lives between those two stages:
after passive vocabulary recognition, before active production in speech.
If the drill requires the student to think hard, it has failed — it should
lower anxiety and build confidence, making them ready for real conversation.

CORE PHILOSOPHY — "Confident Imperfection":
Language acquisition happens when a student risks speaking before they are
certain. Our drills must be designed so that EVERY choice feels safe.
No wrong answers. No combinations that embarrass. No gotchas.
The student who picks any item from any column should produce something
they could say to a native speaker today. If any combination produces
a nonsense or awkward sentence, the drill is broken.

THE RECOGNITION → DRILL → PRODUCTION SEQUENCE (from curriculum audit):
  1. Vocabulary list (See It Say It section) — passive recognition
  2. THIS DRILL — semi-active pattern absorption (the stage you are generating)
  3. Voice session with Daniela — active production / real use
The drill recombines vocabulary the student ALREADY SAW in step 1.
It never introduces new vocabulary. It converts recognition into readiness.

WHAT WE KNOW FAILS (from January 2026 drill audit and March 2026 curriculum audit):
  ✗ "Wide but not deep" — 87% of our drills were listen/repeat (novice audio only).
    The substitution drill adds the depth that was missing.
  ✗ fill_blank drills test recognition, not production. They don't build fluency.
  ✗ Drills that survey full verb paradigms (all 6 conjugations) spread attention
    thin. Students leave remembering none of the forms strongly.
  ✗ Abstract or academic items in Column 2 break the visual scan —
    "en términos generales" doesn't scan; "a la playa" does.
  ✗ Content generated from stale curriculum data fields (required_vocabulary,
    required_grammar) often inherits data quality problems. Generate from
    the lesson vocabulary list and key phrases provided below — trust those,
    not memorized textbook paradigms.

Vocabulary list (up to first 10 items):
${JSON.stringify(vocabList.slice(0, 10), null, 2)}

Key conversation phrases:
${JSON.stringify(keyPhrases, null, 2)}

Generate a JSON object with exactly these fields:

════════════════════════════════════════════════════════════════
THE COMPLETE MADRIGAL PAGE STRUCTURE
Every page in "See It and Say It" / "Magic Key to Spanish" follows
the same four-part format. The four fields below map directly to it.
════════════════════════════════════════════════════════════════

PART 1 (top of the page) — THE ANCHOR
"Voy, I'm going."     "Al, to the."
Two or three building blocks. Widely spaced. Nothing else.
The reader sees the grammatical components before they see any sentences.
The space between them is structural — it lets the eye perceive both
the pieces AND the assembled whole. This is the "Voy / Al" moment.

PART 2 — REPETITION WITH IMAGES (→ negativeItems)
The anchor's components are combined with images of concrete nouns —
but using DIFFERENT nouns than the positive vocabulary grid above.
"No voy al club." [image of a club]. "No voy al teatro." [image of a theater].
Madrigal uses fresh images for the negative section, not the same ones
from the positive grid. The verb form is what stays fixed; both the noun
AND the polarity can vary. The student sees: the pattern works everywhere.

PART 3 — REPETITION WITH QUESTION AND ANSWER (→ questionItems)
"¿Va Pedro al banco?" / "Sí, yo voy al banco." / "No, no voy al banco."
The question uses the ÉL/ELLA form (asking about a named third person).
The answer uses the YO form (student responds in their own voice).
IMPORTANT: NO TÚ FORM. The tú form is eliminated from this curriculum
until explicitly reintroduced. Él/ella questions produce the YO answer
just as naturally as tú questions did — "¿Va Pedro?" → "Yo voy."

PART 4 — GENERAL REPETITION / SUBSTITUTION COLUMNS (→ sentenceColumns)
"voy / va" in Column 1 × many destinations in Column 2.
The eye scans. The brain fires sentences. No conscious effort.

════════════════════════════════════════════════════════════════
Now generate each part:
════════════════════════════════════════════════════════════════

1. "patternLabel" — a short string showing the anchor pattern at the top
   of the lesson page. Format: the 2–3 building block forms separated by " / "
   CRITICAL: NO TÚ FORM anywhere in patternLabel. Use yo / él forms only.
   Example: "Voy / Va / No voy"  or  "Tengo / Tiene / No tengo"
   WRONG: "Voy / No voy / ¿Vas?"  — "¿Vas?" is tú form. Do not use.
   WRONG: "Tengo / No tengo / ¿Tienes?" — "¿Tienes?" is tú form. Do not use.
   This is what the student sees FIRST — the pieces before the whole.
   Keep it minimal. Madrigal's anchors are never more than 3 items.

2. "negativeItems" — PART 2: Repetition with images (4–5 items)
   { "imageWord": string, "negativePhrase": string, "translation": string }

   ── HOW TO GENERATE (Madrigal image repetition rules) ──────────────

   ★ THE ONE RULE THAT OVERRIDES EVERYTHING ELSE ★
   Every single negativePhrase must use THE SAME VERB as the patternLabel.
   The verb NEVER changes across negativeItems. The NOUN changes. Not the verb.

   If patternLabel is "Hablo / Habla / No hablo":
     CORRECT: "No hablo español." / "No hablo inglés." / "No hablo en clase."
     WRONG:   "No compro el libro." (compro is a different verb — forbidden)
     WRONG:   "No escucho música."  (escucho is a different verb — forbidden)
     WRONG:   "No trabajo aquí."    (trabajo is a different verb — forbidden)

   The reason: This section is a pounding machine. The verb hammers in through
   repetition while the noun varies. If the verb changes, the pounding stops.
   You have introduced grammar study instead of pattern absorption.

   Even if the vocabulary list contains multiple verbs — pick ONE. The verb
   in the patternLabel is the one. Use it in every negativePhrase. Every one.

   • imageWord: a bare, concrete, imageable noun from the vocabulary list.
     No articles. No adjectives. The word that an image would depict.
     GOOD: "banco", "playa", "lápiz"   BAD: "español" (a language, not drawable)
     BAD: "mucho" (an adverb, not drawable)   BAD: "bien" (not drawable)
   • negativePhrase: always uses the YO form — "No hablo..." not "No habla..."
     The student is always speaking in their own voice.
   • Each item uses a DIFFERENT NOUN — ideally nouns from a second set in the
     vocabulary list, not the same ones shown in the positive image grid above.
     Madrigal: positive section = hotel/banco/restaurante; negative = club/teatro/cine.
   • 4–5 items total. Never more.

3. "questionItems" — PART 3: Repetition with question and answer (4 items)
   { "imageWord": string, "question": string, "questionTranslation": string,
     "affirmativeAnswer": string, "affirmativeTranslation": string,
     "negativeAnswer": string, "negativeTranslation": string }

   ── HOW TO GENERATE (Madrigal Q&A rules) ──────────────────────────

   ★ SAME RULE AS NEGATIVEITEMS: ONE VERB, USED IN ALL 4 QUESTIONS ★
   The verb in the question is the same verb as the patternLabel. Every question.
   The NOUN changes — the person, the place, the object. The VERB never changes.

   If patternLabel is "Hablo / Habla / No hablo":
     CORRECT: "¿Habla María español?"  / "¿Habla Pedro inglés?"
     WRONG:   "¿Estudia Pedro inglés?"  (estudia is a different verb — forbidden)
     WRONG:   "¿Trabaja Ana en la escuela?" (trabaja is different — forbidden)
     WRONG:   "¿Necesita Carlos un lápiz?"  (necesita is different — forbidden)

   Madrigal's Q&A pages use one verb per spread: "¿Va al banco?" / "¿Va al teatro?"
   The place changes. The verb is "va" every time. The student hears the same form
   over and over until it is automatic.

   CRITICAL — NO TÚ FORM anywhere. The question uses ÉL / ELLA only:
     "¿Va Pedro al banco?"       NOT "¿Vas al banco?"
     "¿Habla María español?"     NOT "¿Hablas español?"
   The student answers in the YO form — their own voice:
     "Sí, yo hablo español."     / "No, no hablo español."
   Use different names across the 4 items: Pedro, María, Carlos, Ana.

   • affirmativeAnswer: YO form, complete sentence — "Sí, yo hablo español."
   • negativeAnswer: complete sentence with double no — "No, no hablo español."
   • imageWord: bare concrete noun from the question. Must be imageable.
     "español" is a language — not imageable. Use "libro", "lápiz", "cuaderno."
   • Use a different vocabulary NOUN for each of the 4 items.
     The verb is fixed. Only the noun varies.

4. "sentenceColumns" — PART 4: General repetition / substitution columns
   { "label": string, "items": [{ "text": string, "translation": string }] }

   ── HOW TO GENERATE (Madrigal substitution drill — full rules below) ──
   { "label": string (short column header), "items": [{ "text": string, "translation": string }] }

   ════════════════════════════════════════════════════════════════
   THE "SEE IT AND SAY IT" VISUAL SCANNING PHILOSOPHY
   (Madrigal method — this overrides all traditional pedagogy instincts)
   ════════════════════════════════════════════════════════════════

   This is NOT a fill-in-the-blank exercise. It is not a conjugation table. It is a
   VISUAL PERCEPTION ENGINE. The student's eye scans across the columns and their brain
   automatically assembles sentences — the same way eyes scan a multiplication table and
   produce products without doing arithmetic. The permutations happen passively, at a
   glance, without conscious effort.

   THE GOAL: maximize the number of correct sentences a student's brain generates per
   second of looking at the screen, while minimizing the cognitive work required to do so.

   ── COLUMN 1 — The fixed anchor (1–2 items ONLY) ──────────────────
   Pick ONE verb. Use only its two most essential forms:
     • yo form  (1st person singular) — "voy", "hablo", "tengo"  — "I do X"
     • él/ella form (3rd person singular) — "va", "habla", "tiene" — "he/she does X"
   These two forms cover the vast majority of real-world use. That is all Column 1 gets.

   WHY NOT ALL 6 CONJUGATIONS? This is the most important rule.
   Traditional pedagogy surveys the whole paradigm. This is exactly wrong here.
   - 6 forms × 7 objects = 42 combinations the brain must check one by one (studying)
   - 2 forms × 7 objects = 14 combinations the eye generates in a single scan (acquiring)
   A long Column 1 destroys the "fixed anchor" effect. The eye has to travel; the brain
   has to hold 6 unfamiliar things in working memory; the scan becomes a study session.
   The tú form and plural forms belong in a LATER chapter as "one small change."

   NEVER mix different verbs in Column 1 (hablar + comprar + trabajar = disaster).
   Every Column 2 object must work with EVERY Column 1 verb form — or the student hits
   a nonsense sentence ("Yo hablo un lápiz") and stops trusting the material.

   ── COLUMN 2 — The vocabulary cluster (5–8 items) ────────────────────

   ★ THE VOCABULARY CLUSTER PRINCIPLE ★
   Column 2 is not "variety for variety's sake." It is the lesson's vocabulary cluster —
   the set of nouns that share a semantic field and pair naturally with the anchored verb.

   Madrigal Lesson 1 (ir): Column 2 = places in a city — hotel, banco, restaurante, teatro, cine, parque
   A classroom lesson (usar): Column 2 = classroom objects — silla, mesa, papel, lápiz, tiza, pizarra
   A family lesson (tener): Column 2 = family members — hermano, padre, madre, tío, abuelo, primo

   The verb bonds with the cluster through repetition. That is the whole point.
   Do NOT put different categories of nouns in Column 2 — that is mixing semantic fields.
   Do NOT put adverbs (mucho, bien) alongside nouns (silla, mesa) — different dimensions.
   Do NOT put manner adverbs alongside place adverbs — different dimensions.

   Column 2 rules:
   1. Every item must be semantically compatible with EVERY verb form in Column 1.
      If it only works with one form, leave it out entirely.
   2. ONE semantic dimension only — all city places, OR all classroom objects, OR all
      family members, OR all foods. Never mix: "a la playa" [destination] with "mucho"
      [manner] are different dimensions and break the scan.
   3. CONCRETE AND IMAGEABLE ONLY. "a la playa" works — you see a beach. "generalmente"
      doesn't — it's abstract. Concrete nouns and named places pass. Adverbs of manner
      (mucho, bien) may be used only as a cluster by themselves, not mixed with nouns.
   4. ORDER BY FREQUENCY OF USE — most useful item first. Not alphabetical. Not random.
   5. PULL FROM THE VOCABULARY LIST PROVIDED. Do not invent words not in the lesson.
      If the list has 8 nouns in the same semantic field, use 6–7 of them.
   6. Items should be visually distinct — different lengths, different starting words.
   7. 5–8 items. Fewer = not enough permutations. More = the column becomes a list.

   Good examples:
     ir   → a la playa / al banco / a la biblioteca / al mercado / a casa / al restaurante
     hablar → español / inglés / francés / mucho / bien / todos los días
     tener  → hambre / sed / frío / calor / miedo / sueño

   ── COLUMN LABELS — use question words, not category names ──────────
   Labels that work: "Where?" / "What?" / "How?" / "When?" / "With whom?"
   Labels that don't work: "Destinations" / "Objects" / "Verb Forms" / "Complements"
   A question word primes the student to connect the verb (Column 1) with the answer
   (Column 2). It also scans in under a second. A category name makes the student
   think about grammar, which breaks the acquisition flow.

   ── TRANSLATION RULES — gloss only, never explain ───────────────────
   Translation should be the shortest accurate English equivalent. Not a definition.
   GOOD: "to the beach" / "a lot" / "at school"
   BAD: "to the beach (a common vacation destination)" / "a lot (used as an adverb)"
   Economy in the translation preserves the scanning rhythm. Verbose translations
   make the student read, not scan.

   ── COLUMN 3 — Optional only if every 3-way combo is valid ─────────
   Add a third column only when a third dimension is central to the vocabulary AND every
   Column1 × Column2 × Column3 combination produces a correct, meaningful sentence.
   When in doubt: omit Column 3. A clean 2-column drill beats a broken 3-column drill.

   ── THE ANTI-PATTERN TO AVOID ───────────────────────────────────────
   Your default instinct will be to write something like:
     Column 1: yo voy / tú vas / él va / nosotros vamos / vosotros vais / ellos van
     Column 2: a la playa / al banco
   This is wrong. It puts maximum cognitive load in Column 1 (6 unfamiliar forms) and
   minimum variation in Column 2 (2 objects). The brain cannot scan it — it has to study.
   The correct direction is always the opposite: minimum in Column 1, maximum in Column 2.

Return ONLY valid JSON, no markdown, no explanation.`;

        const response = await anthropic.messages.create({
          model: 'claude-sonnet-4-5',
          max_tokens: 1500,
          messages: [{ role: 'user', content: prompt }],
        });

        const raw = (response.content[0] as { type: string; text: string }).text.trim();
        const cleaned = raw.startsWith('```') ? raw.replace(/^```[a-z]*\n?/, '').replace(/\n?```$/, '') : raw;
        const data = JSON.parse(cleaned);

        // Write-through to DB (L2 cache) — fire and forget
        db.execute(
          drizzleSql`UPDATE textbook_lesson_content SET micro_cycle_data = ${JSON.stringify(data)}::jsonb WHERE lesson_id = ${lessonId} AND language = ${language}`
        ).catch((err: any) => console.warn('[MicroCycle] DB write failed:', err.message));

        // Store in L1 cache
        microCycleCache.set(cacheKey, data);
        return res.json({ ...data, fromCache: false });
      } catch (error: any) {
        console.error('[MicroCycle]', error.message);
        res.status(500).json({ error: error.message });
      }
    });
  }

  // Resolve vocabulary images from textbook_lesson_content.vocabulary_list
  // Returns { images: { [word]: { url: string; source: string } } }
  app.get('/api/textbook-content/:lessonId/vocab-images', isAuthenticated, async (req: any, res: Response) => {
    try {
      const { lessonId } = req.params;
      const { language } = req.query as { language?: string };
      if (!language) return res.status(400).json({ error: 'language query param required' });

      const { getUserDb } = await import('./db');
      const { sql: drizzleSql } = await import('drizzle-orm');
      const db = getUserDb();
      const row = await db.execute(
        drizzleSql`SELECT vocabulary_list FROM textbook_lesson_content WHERE lesson_id = ${lessonId} LIMIT 1`
      );
      if (row.rows.length === 0) return res.json({ images: {} });

      const vocabList = (row.rows[0].vocabulary_list ?? []) as Array<{ word: string; translation?: string }>;
      if (vocabList.length === 0) return res.json({ images: {} });

      const { resolveVocabularyImage } = await import('./services/vocabulary-image-resolver');
      const images: Record<string, { url: string; source: string }> = {};
      const concurrency = 3;

      for (let i = 0; i < vocabList.length; i += concurrency) {
        const batch = vocabList.slice(i, i + concurrency);
        const results = await Promise.all(
          batch.map(async (item) => {
            try {
              const result = await resolveVocabularyImage({
                word: item.word,
                language,
                description: item.translation ?? item.word,
                libraryOnly: true,
              });
              return { word: item.word, url: result.imageUrl, source: result.source };
            } catch {
              return { word: item.word, url: null, source: 'error' };
            }
          })
        );
        for (const r of results) {
          if (r.url && r.source !== 'placeholder') images[r.word] = { url: r.url, source: r.source };
        }
      }

      res.json({ images });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Fetch cached vocab images for an arbitrary list of words (used by SocialPhraseUnit).
  // Does NOT depend on a lesson's vocabulary_list — looks up each word directly from cache.
  app.post('/api/vocab-images/by-word-list', isAuthenticated, async (req: any, res: Response) => {
    try {
      const { language = 'spanish', words } = req.body;
      if (!Array.isArray(words) || words.length === 0) return res.json({ images: {} });

      const { resolveVocabularyImage } = await import('./services/vocabulary-image-resolver');
      const images: Record<string, { url: string; source: string }> = {};
      const concurrency = 4;

      for (let i = 0; i < words.length; i += concurrency) {
        const batch = (words as string[]).slice(i, i + concurrency);
        const results = await Promise.all(
          batch.map(async (word: string) => {
            try {
              const result = await resolveVocabularyImage({ word, language, description: word, libraryOnly: true });
              return { word, url: result.imageUrl, source: result.source };
            } catch {
              return { word, url: null, source: 'error' };
            }
          })
        );
        for (const r of results) {
          if (r.url && r.source !== 'placeholder') images[r.word] = { url: r.url, source: r.source };
        }
      }

      res.json({ images });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

