  // Bust cache for number/day words and re-seed them with correct scene prompts
  app.post('/api/admin/vocab-images/fix-numbers-days', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { language = 'spanish' } = req.body;
      const { bustVocabImageCache, NUMBERS_DAYS_CACHE_KEYS, NUMBERS_DAYS_WORDS, normalizeForOverride, SCENE_OVERRIDES } = await import('./services/vocab-image-seed-service');
      const { NUMBER_CONCEPT_KEYS, resolveVocabularyImage } = await import('./services/vocabulary-image-resolver');
      const langKeys = NUMBERS_DAYS_CACHE_KEYS[language] ?? NUMBERS_DAYS_CACHE_KEYS['spanish'];
      // Bust both language-specific keys AND shared concept keys so stale concept
      // images don't survive a Fix Stale operation.
      const deleted = await bustVocabImageCache([...langKeys, ...NUMBER_CONCEPT_KEYS]);
      const jobId = `vocab-fix-numbers-${language}-${Date.now()}`;
      // Regenerate directly — numbers/days may not be in the curriculum for all languages
      const words: string[] = NUMBERS_DAYS_WORDS[language] ?? NUMBERS_DAYS_WORDS['spanish'] ?? [];
      (async () => {
        for (const word of words) {
          try {
            const sceneOverride = SCENE_OVERRIDES[normalizeForOverride(word)];
            await resolveVocabularyImage({ word, language, description: word, scene: sceneOverride });
          } catch (e: any) {
            console.error(`[VocabFix] Failed to regenerate number/day "${word}" (${language}):`, e.message);
          }
        }
        console.log(`[VocabFix] Finished regenerating ${words.length} ${language} numbers/days (job ${jobId})`);
      })().catch((e: any) => console.error('[VocabFix] Fatal error:', e.message));
      res.json({ deleted, jobId, message: `Busted ${deleted} stale number/day images (including concept keys). Regenerating ${words.length} words in background.` });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  /**
   * Image Audit — two-step preview/apply flow for concept-key images.
   *
   * Step 1: POST /api/admin/vocab-images/regen-preview-key
   *   Generates a DALL-E 3 candidate and stores it server-side (in auditPreviewStore).
   *   Returns the data URL for display — nothing is written to GCS yet.
   *
   * Step 2: POST /api/admin/vocab-images/regen-apply-key
   *   Takes the approved data URL from the store and writes it to GCS, replacing the
   *   existing file. Clears the preview from memory.
   */
  const auditPreviewStore = new Map<string, string>(); // conceptKey → data URL

  app.post('/api/admin/vocab-images/regen-preview-key', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { conceptKey, prompt } = req.body;
      if (!conceptKey || typeof conceptKey !== 'string') return res.status(400).json({ error: 'conceptKey is required' });
      if (!prompt || typeof prompt !== 'string') return res.status(400).json({ error: 'prompt is required' });

      const safeKey = conceptKey.replace(/[^a-z0-9_]/g, '');
      if (!safeKey.startsWith('vocab_')) return res.status(400).json({ error: 'conceptKey must start with vocab_' });

      console.log(`[AuditPreview] Generating candidate for ${safeKey}.png`);
      const dataUrl = await generateImageWithGemini(prompt);
      if (!dataUrl) return res.status(500).json({ error: 'Image generation failed — no data returned' });

      // Hold in memory — nothing touches GCS yet
      auditPreviewStore.set(safeKey, dataUrl);
      console.log(`[AuditPreview] ✓ Candidate ready for ${safeKey} (${Math.round(dataUrl.length / 1024)}KB)`);
      res.json({ conceptKey: safeKey, previewDataUrl: dataUrl });
    } catch (error: any) {
      console.error('[AuditPreview] Error:', error.message);
      res.status(500).json({ error: error.message });
    }
  });

  app.post('/api/admin/vocab-images/regen-apply-key', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { conceptKey } = req.body;
      if (!conceptKey || typeof conceptKey !== 'string') return res.status(400).json({ error: 'conceptKey is required' });

      const safeKey = conceptKey.replace(/[^a-z0-9_]/g, '');
      const dataUrl = auditPreviewStore.get(safeKey);
      if (!dataUrl) return res.status(404).json({ error: `No pending preview for ${safeKey} — generate a preview first` });

      const base64 = dataUrl.replace(/^data:image\/\w+;base64,/, '');
      const buffer = Buffer.from(base64, 'base64');

      const { uploadPublicBuffer } = await import('./services/image-storage');
      await uploadPublicBuffer(`${safeKey}.png`, buffer, 'image/png'); // gcs-guard-exempt: result discarded; proxy URL constructed manually in response
      auditPreviewStore.delete(safeKey);
      console.log(`[AuditApply] ✓ Applied preview → ${safeKey}.png in GCS`);
      res.json({ url: `/api/media/ai-image/${safeKey}.png`, conceptKey: safeKey, message: `Applied — ${safeKey}.png replaced in GCS` });
    } catch (error: any) {
      console.error('[AuditApply] Error:', error.message);
      res.status(500).json({ error: error.message });
    }
  });

