  app.post('/api/admin/vocab-images/fix-social-phrases', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { language = 'spanish' } = req.body;
      const { bustVocabImageCache, SOCIAL_PHRASES_WORDS, SOCIAL_PHRASES_CACHE_KEYS, normalizeForOverride, SCENE_OVERRIDES } = await import('./services/vocab-image-seed-service');
      const { resolveVocabularyImage } = await import('./services/vocabulary-image-resolver');
      const keys = SOCIAL_PHRASES_CACHE_KEYS[language] ?? [];
      const deleted = await bustVocabImageCache(keys);
      const jobId = `vocab-fix-social-${language}-${Date.now()}`;
      const words: string[] = SOCIAL_PHRASES_WORDS[language] ?? [];
      (async () => {
        for (const word of words) {
          try {
            const overrideKey = normalizeForOverride(word);
            const sceneOverride = SCENE_OVERRIDES[`${language}:${overrideKey}`] ?? SCENE_OVERRIDES[overrideKey];
            await resolveVocabularyImage({ word, language, description: word, scene: sceneOverride });
          } catch (e: any) {
            console.error(`[VocabFix] Failed social phrase "${word}" (${language}):`, e.message);
          }
        }
        console.log(`[VocabFix] Finished regenerating ${words.length} ${language} social phrases (job ${jobId})`);
      })().catch((e: any) => console.error('[VocabFix] Fatal error:', e.message));
      res.json({ deleted, jobId, words, message: `Busted ${deleted} stale images. Regenerating ${words.length} social phrases in background.` });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // ─── BATCH: Fix numbers/days for ALL languages at once ───────────────────────
  app.post('/api/admin/vocab-images/fix-all-numbers', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const allLangs = ['spanish', 'french', 'german', 'italian', 'portuguese', 'english', 'japanese', 'korean', 'mandarin', 'hebrew'];
      const { bustVocabImageCache, NUMBERS_DAYS_CACHE_KEYS, NUMBERS_DAYS_WORDS, normalizeForOverride, SCENE_OVERRIDES } = await import('./services/vocab-image-seed-service');
      const { NUMBER_CONCEPT_KEYS, resolveVocabularyImage } = await import('./services/vocabulary-image-resolver');
      let totalDeleted = 0;
      for (const lang of allLangs) {
        const keys = NUMBERS_DAYS_CACHE_KEYS[lang] ?? [];
        totalDeleted += await bustVocabImageCache([...keys, ...NUMBER_CONCEPT_KEYS]);
      }
      const jobId = `vocab-fix-all-numbers-${Date.now()}`;
      (async () => {
        for (const lang of allLangs) {
          const words: string[] = NUMBERS_DAYS_WORDS[lang] ?? [];
          for (const word of words) {
            try {
              const overrideKey = normalizeForOverride(word);
              const sceneOverride = SCENE_OVERRIDES[`${lang}:${overrideKey}`] ?? SCENE_OVERRIDES[overrideKey];
              await resolveVocabularyImage({ word, language: lang, description: word, scene: sceneOverride });
            } catch (e: any) {
              console.error(`[VocabFix] Failed number/day ${word} (${lang}):`, e.message);
            }
          }
          console.log(`[VocabFix] Finished ${lang} numbers/days`);
        }
        console.log(`[VocabFix] ALL numbers/days done (job ${jobId})`);
      })().catch((e: any) => console.error('[VocabFix] Fatal fix-all-numbers:', e.message));
      res.json({ deleted: totalDeleted, jobId, message: `Busted ${totalDeleted} stale number/day images across all languages. Regenerating in background.` });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // ─── BATCH: Generate images for ALL scenario zones that don't have one ────────
  app.post('/api/admin/generate-all-zone-images', async (req: any, res: Response) => {
    try {
      const force = req.body?.force === true;
      const { scenarioZones, scenarios } = await import('@shared/schema');
      const sharedDb = getSharedDb();
      const zones = force
        ? await sharedDb.select().from(scenarioZones)
        : await sharedDb.select().from(scenarioZones).where(isNull(scenarioZones.imageUrl));
      // Build scenario title map for media library records
      const scenarioList = await sharedDb.select({ id: scenarios.id, title: scenarios.title }).from(scenarios);
      const scenarioTitleMap = Object.fromEntries(scenarioList.map((s: any) => [s.id, s.title]));
      const jobId = `zone-images-all-${Date.now()}`;
      (async () => {
        for (const zone of zones) {
          const rawPrompt = zone.imagePrompt || `${scenarioTitleMap[zone.scenarioId] ?? 'Scenario'} — ${zone.name}`;
          if (!zone.imagePrompt) { console.warn(`[ZoneImages] Zone ${zone.name} has no imagePrompt — using fallback: "${rawPrompt}"`); }
          try {
            const styledPrompt = await buildZoneImagePrompt(rawPrompt);
            const dataUrl = await generateImageWithGemini(styledPrompt);
            await sharedDb.update(scenarioZones).set({ imageUrl: dataUrl }).where(eq(scenarioZones.id, zone.id));
            // Mirror in the Image Library
            const scenarioTitle = scenarioTitleMap[zone.scenarioId] ?? 'Scenario';
            await saveZoneImageToMediaLibrary(dataUrl, zone.name, scenarioTitle, zone.imagePrompt);
            console.log(`[ZoneImages] Generated image for ${zone.name}`);
          } catch (e: any) {
            console.error(`[ZoneImages] Failed for ${zone.name}:`, e.message);
          }
        }
        console.log(`[ZoneImages] All ${zones.length} zone images done (job ${jobId})`);
      })().catch((e: any) => console.error('[ZoneImages] Fatal:', e.message));
      res.json({ total: zones.length, jobId, message: `Generating images for ${zones.length} zones in background.` });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // ─── POST: Backfill existing zone images into the media library ───────────────
  app.post('/api/admin/backfill-zone-images-to-media', async (req: any, res: Response) => {
    try {
      const { scenarioZones, scenarios } = await import('@shared/schema');
      const sharedDb = getSharedDb();
      const zones = await sharedDb.select().from(scenarioZones).where(isNotNull(scenarioZones.imageUrl));
      const scenarioList = await sharedDb.select({ id: scenarios.id, title: scenarios.title }).from(scenarios);
      const scenarioTitleMap = Object.fromEntries(scenarioList.map((s: any) => [s.id, s.title]));
      let saved = 0;
      for (const zone of zones) {
        if (!zone.imageUrl) continue;
        try {
          const scenarioTitle = scenarioTitleMap[zone.scenarioId] ?? 'Scenario';
          await saveZoneImageToMediaLibrary(zone.imageUrl, zone.name, scenarioTitle, zone.imagePrompt);
          saved++;
        } catch (e: any) {
          console.warn(`[BackfillZone] Skipped ${zone.name}: ${e.message}`);
        }
      }
      res.json({ total: zones.length, saved, message: `Backfilled ${saved} of ${zones.length} zone images to media library.` });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // ─── GET: All zone image status for admin panel ───────────────────────────────
  app.get('/api/admin/all-zone-images-status', async (req: any, res: Response) => {
    try {
      const { scenarioZones, scenarios } = await import('@shared/schema');
      const sharedDb = getSharedDb();
      const zones = await sharedDb
        .select({
          id: scenarioZones.id,
          name: scenarioZones.name,
          zoneOrder: scenarioZones.zoneOrder,
          imageUrl: scenarioZones.imageUrl,
          imagePrompt: scenarioZones.imagePrompt,
          scenarioId: scenarioZones.scenarioId,
          nextScenarioSlug: scenarioZones.nextScenarioSlug,
        })
        .from(scenarioZones)
        .orderBy(scenarioZones.scenarioId, scenarioZones.zoneOrder);
      // Also get scenario names
      const scenarioList = await sharedDb.select({ id: scenarios.id, title: scenarios.title }).from(scenarios);
      const scenarioMap = Object.fromEntries(scenarioList.map(s => [s.id, s.title]));
      const withNames = zones.map(z => ({ ...z, scenarioTitle: scenarioMap[z.scenarioId] || z.scenarioId }));
      res.json({ zones: withNames, total: withNames.length, withImages: withNames.filter(z => z.imageUrl).length });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });


