  // Seed vocab images for ALL languages
  app.post('/api/admin/vocab-images/seed-all', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { languages } = req.body; // optional: array of language names to seed
      const jobId = `vocab-seed-all-${Date.now()}`;
      const { seedAllVocabImages } = await import('./services/vocab-image-seed-service');
      seedAllVocabImages(jobId, languages).catch((e: any) =>
        console.error('[BulkVocabSeed] Fatal error:', e.message)
      );
      res.json({ jobId, message: 'Bulk vocab image seeding started — poll /api/admin/vocab-images/seed-all-progress/:jobId' });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // ── Bulk bust + reseed: wipe all AI-generated vocab images for given languages, then regenerate ──

  const bustReseedJobs = new Map<string, { status: string; busted: number; languages: string[]; log: string[] }>();

  app.post('/api/admin/vocab-images/bust-and-reseed', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { languages, dryRun = false } = req.body as { languages?: string[]; dryRun?: boolean };

      const ALL_LANGUAGES = ['spanish','french','german','italian','portuguese','japanese','korean','mandarin','english'];
      const targetLangs: string[] = (languages && languages.length > 0) ? languages : ALL_LANGUAGES;

      // Count AI-generated vocab images for these languages (dry-run or pre-report)
      const db = getSharedDb();
      const countRows = await db.execute(
        sql`SELECT language, COUNT(*)::int AS cnt
            FROM media_files
            WHERE language = ANY(${sql.raw(`ARRAY[${targetLangs.map(l => `'${l}'`).join(',')}]`)})
              AND image_source = 'ai_generated'
              AND search_query LIKE 'vocab_%'
            GROUP BY language
            ORDER BY language`
      );
      const counts = (countRows as any).rows ?? countRows;
      const totalCount = counts.reduce((sum: number, r: any) => sum + (r.cnt ?? 0), 0);

      if (dryRun) {
        return res.json({ dryRun: true, languages: targetLangs, breakdown: counts, total: totalCount });
      }

      // Fire off the bust + reseed in the background
      const jobId = `bust-reseed-${Date.now()}`;
      const job = { status: 'running', busted: 0, languages: targetLangs, log: [] as string[] };
      bustReseedJobs.set(jobId, job);

      (async () => {
        try {
          job.log.push(`Starting bust for ${targetLangs.join(', ')} — ${totalCount} AI-generated images`);

          // Delete AI-generated vocab images for these languages
          const delResult = await db.execute(
            sql`DELETE FROM media_files
                WHERE language = ANY(${sql.raw(`ARRAY[${targetLangs.map(l => `'${l}'`).join(',')}]`)})
                  AND image_source = 'ai_generated'
                  AND search_query LIKE 'vocab_%'`
          );
          const deleted = (delResult as any).rowCount ?? 0;
          job.busted = deleted;
          job.log.push(`Busted ${deleted} cached images — starting reseed`);

          // Kick off seedVocabImages for each language sequentially
          const { seedVocabImages } = await import('./services/vocab-image-seed-service');
          for (const lang of targetLangs) {
            const subJobId = `vocab-seed-${lang}-${Date.now()}`;
            job.log.push(`Seeding ${lang}…`);
            await seedVocabImages(lang, subJobId);
            job.log.push(`✓ ${lang} complete`);
          }

          job.status = 'complete';
          job.log.push('All languages reseeded');
        } catch (err: any) {
          job.status = 'error';
          job.log.push(`Error: ${err.message}`);
          console.error('[BustReseed] Fatal:', err.message);
        }
      })();

      res.json({ jobId, dryRun: false, languages: targetLangs, willBust: totalCount, message: `Poll /api/admin/vocab-images/bust-and-reseed/${jobId}` });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.get('/api/admin/vocab-images/bust-and-reseed/:jobId', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    const job = bustReseedJobs.get(req.params.jobId);
    if (!job) return res.status(404).json({ error: 'Job not found' });
    res.json(job);
  });

  // ── Vocab Drill Seed (converts textbook_lesson_content → curriculum_drill_items) ──

  // In-memory job store for drill seed jobs
  const vocabDrillSeedJobs = new Map<string, { status: string; log: string[]; results?: any[] }>();

  app.post('/api/admin/seed-vocab-drills', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { languages } = req.body; // optional: restrict to specific languages
      const jobId = `vocab-drill-seed-${Date.now()}`;
      const job = { status: 'running', log: [] as string[], results: undefined as any };
      vocabDrillSeedJobs.set(jobId, job);

      const { seedVocabDrillItems } = await import('./services/vocab-drill-seed-service');
      seedVocabDrillItems({
        languages: languages ?? undefined,
        onProgress: (msg: string) => {
          console.log(msg);
          job.log.push(msg);
        },
      }).then((results) => {
        job.status = 'done';
        job.results = results;
        console.log('[VocabDrillSeed] All languages complete');
      }).catch((err: any) => {
        job.status = 'error';
        job.log.push(`Fatal: ${err.message}`);
        console.error('[VocabDrillSeed] Fatal error:', err.message);
      });

      res.json({ jobId, message: 'Vocab drill seeding started — poll /api/admin/seed-vocab-drills/status/:jobId' });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.get('/api/admin/seed-vocab-drills/status/:jobId', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    const job = vocabDrillSeedJobs.get(req.params.jobId);
    if (!job) return res.status(404).json({ error: 'Job not found' });
    res.json(job);
  });

  // Poll single-language seed job
  app.get('/api/admin/vocab-images/seed-progress/:jobId', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { jobId } = req.params;
      const { vocabSeedJobs } = await import('./services/vocab-image-seed-service');
      const job = vocabSeedJobs.get(jobId);
      if (!job) return res.status(404).json({ error: 'Job not found' });
      res.json(job);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Poll bulk seed-all job
  app.get('/api/admin/vocab-images/seed-all-progress/:jobId', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { jobId } = req.params;
      const { bulkVocabSeedJobs, vocabSeedJobs } = await import('./services/vocab-image-seed-service');
      const bulk = bulkVocabSeedJobs.get(jobId);
      if (!bulk) return res.status(404).json({ error: 'Job not found' });
      // Attach per-language sub-job details
      const subJobs: Record<string, any> = {};
      for (const lang of bulk.languages) {
        const subJobId = `${jobId}-${lang}`;
        const sub = vocabSeedJobs.get(subJobId);
        if (sub) subJobs[lang] = sub;
      }
      res.json({ ...bulk, subJobs });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // ─── Canonical vocabulary registry audit ──────────────────────────────────
  // GET /api/admin/vocab-audit?language=spanish&status=unrouted
  // Queries actual lesson required_vocabulary from DB, classifies each word
  // through the four-tier routing pipeline, and reports routing completeness.
  app.get('/api/admin/vocab-audit', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { lookupCanonicalConcept, CANONICAL_UNITS } = await import('./data/canonical-vocabulary');
      const { CONCEPT_KEY_MAP, normalizeWord } = await import('./services/vocabulary-image-resolver');
      const { SCENE_OVERRIDES, normalizeForOverride } = await import('./services/vocab-image-seed-service');
      const { getUserDb } = await import('./db');
      const { sql: rawSql } = await import('drizzle-orm');
      const db = getUserDb();

      // Language code → canonical name mapping
      type CanonicalLang = 'english'|'french'|'german'|'italian'|'portuguese'|'spanish'|'japanese'|'korean'|'mandarin';
      const LANG_CODE_MAP: Record<string, CanonicalLang> = {
        en: 'english', english: 'english',
        fr: 'french',  french: 'french',
        de: 'german',  german: 'german',
        it: 'italian', italian: 'italian',
        pt: 'portuguese', portuguese: 'portuguese',
        es: 'spanish', spanish: 'spanish',
        ja: 'japanese', japanese: 'japanese',
        ko: 'korean',  korean: 'korean',
        zh: 'mandarin', mandarin: 'mandarin',
        cn: 'mandarin',
      };

      function toCanonicalLang(raw: string): CanonicalLang | null {
        return LANG_CODE_MAP[raw.toLowerCase().trim()] ?? null;
      }

      // Filter params — accept both short codes and full names
      const rawLang = (req.query.language as string | undefined)?.toLowerCase().trim();
      const langFilter = rawLang ? toCanonicalLang(rawLang) : undefined;
      const statusFilter = req.query.status as string | undefined; // canonical|shared_concept|scene_override|unrouted
      const unitFilter   = (req.query.unit as string | undefined)?.toLowerCase().trim();
      const levelFilter  = (req.query.level as string | undefined)?.toLowerCase().trim(); // e.g. novice_low, intermediate, advanced

      /** Classify a single word through the four-tier routing chain */
      function classifyWord(word: string, canonLang: CanonicalLang): { status: string; key: string | null } {
        // Tier 0: canonical registry
        const canonicalKey = lookupCanonicalConcept(word, canonLang);
        if (canonicalKey) return { status: 'canonical', key: canonicalKey };

        // Tier 1: CONCEPT_KEY_MAP (shared concept map)
        const norm = normalizeWord(word);
        const conceptKey = (CONCEPT_KEY_MAP as Record<string, string>)[norm] ?? null;
        if (conceptKey) return { status: 'shared_concept', key: conceptKey };

        // Tier 2: SCENE_OVERRIDES (character scene)
        const overrideKey = normalizeForOverride(word);
        if ((SCENE_OVERRIDES as Record<string, string>)[overrideKey]) {
          return { status: 'scene_override', key: null };
        }

        return { status: 'unrouted', key: null };
      }

      // Fetch all lessons with their required_vocabulary, joined with unit and path for context
      // langFilter is already sanitized against LANG_CODE_MAP (only known-safe values)

      const lessonRows = await db.execute(rawSql`
        SELECT
          cl.id           AS lesson_id,
          cl.name         AS lesson_name,
          cl.required_vocabulary,
          cu.id           AS unit_id,
          cu.name         AS unit_name,
          cu.chapter_type,
          cp.language     AS path_language,
          cp.start_level  AS path_start_level,
          cp.end_level    AS path_end_level
        FROM curriculum_lessons cl
        JOIN curriculum_units cu ON cu.id = cl.curriculum_unit_id
        JOIN curriculum_paths cp ON cp.id = cu.curriculum_path_id
        WHERE cl.required_vocabulary IS NOT NULL
          AND array_length(cl.required_vocabulary, 1) > 0
          ${langFilter  ? rawSql`AND LOWER(cp.language)    = ${langFilter}`  : rawSql``}
          ${levelFilter ? rawSql`AND (LOWER(cp.start_level) = ${levelFilter} OR LOWER(cp.end_level) = ${levelFilter})` : rawSql``}
        ORDER BY cp.language, cu.order_index, cl.order_index
      `);

      // Aggregate stats
      const byUnit: Record<string, any> = {};
      let total = 0, routed = 0, unrouted = 0;
      const byLanguage: Record<string, { total: number; routed: number }> = {};

      for (const row of lessonRows.rows as any[]) {
        const words: string[] = Array.isArray(row.required_vocabulary) ? row.required_vocabulary : [];
        if (!words.length) continue;

        const rawPathLang = (row.path_language as string)?.toLowerCase().trim() ?? '';
        const canonLang: CanonicalLang | null = LANG_CODE_MAP[rawPathLang] ?? null;
        if (!canonLang) continue; // skip rows with unrecognised language

        // Apply unit filter if provided (case-insensitive partial match on unit name)
        const unitNameLower = (row.unit_name as string)?.toLowerCase() ?? '';
        if (unitFilter && !unitNameLower.includes(unitFilter)) continue;

        const unitKey = `${canonLang}__${row.unit_name as string}`;

        if (!byUnit[unitKey]) {
          byUnit[unitKey] = {
            language: canonLang,
            unitId: row.unit_id,
            unitName: row.unit_name,
            chapterType: row.chapter_type,
            lessons: [],
          };
        }
        if (!byLanguage[canonLang]) byLanguage[canonLang] = { total: 0, routed: 0 };

        const lessonItems: any[] = [];
        for (const word of words) {
          const { status, key } = classifyWord(word, canonLang);
          // Always count totals; only show items matching statusFilter (if set)
          total++;
          byLanguage[canonLang].total++;
          if (status !== 'unrouted') {
            routed++;
            byLanguage[canonLang].routed++;
          } else {
            unrouted++;
          }
          if (!statusFilter || status === statusFilter) {
            lessonItems.push({ word, status, key });
          }
        }

        if (lessonItems.length > 0) {
          byUnit[unitKey].lessons.push({
            lessonId: row.lesson_id,
            lessonName: row.lesson_name,
            items: lessonItems,
          });
        }
      }

      // Also pull the canonical registry catalogue for reference (not DB-dependent)
      const registryCatalog: Record<string, number> = {};
      for (const [theme, concepts] of Object.entries(CANONICAL_UNITS)) {
        registryCatalog[theme] = concepts.length;
      }

      res.json({
        summary: {
          total,
          routed,
          unrouted,
          coveragePercent: total > 0 ? Math.round((routed / total) * 100) : 0,
        },
        byLanguage: Object.entries(byLanguage).map(([lang, s]) => ({
          language: lang,
          total: s.total,
          routed: s.routed,
          unrouted: s.total - s.routed,
          coveragePercent: s.total > 0 ? Math.round((s.routed / s.total) * 100) : 0,
        })),
        filters: { language: langFilter ?? 'all', level: levelFilter ?? 'all', unit: unitFilter ?? 'all', status: statusFilter ?? 'all' },
        byUnit,
        registryCatalog,
      });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // POST /api/admin/vocab-add-concept — log an admin suggestion to add an unrouted word
  // to the canonical registry or CONCEPT_KEY_MAP.  Persisted in-memory (survives restart
  // only until the server restarts — the admin is expected to also update the source files).
  const vocabConceptSuggestions: Array<{ word: string; language: string; suggestedKey: string; note: string; addedAt: string }> = [];
  app.post('/api/admin/vocab-add-concept', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { word, language, suggestedKey, note } = req.body ?? {};
      if (!word || !language || !suggestedKey) {
        return res.status(400).json({ error: 'word, language, and suggestedKey are required' });
      }
      const entry = { word: String(word), language: String(language), suggestedKey: String(suggestedKey), note: String(note ?? ''), addedAt: new Date().toISOString() };
      vocabConceptSuggestions.push(entry);
      console.log(`[VocabAudit] Admin added concept suggestion: "${word}" (${language}) → "${suggestedKey}"`);
      res.json({ success: true, entry, totalSuggestions: vocabConceptSuggestions.length });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // GET /api/admin/vocab-add-concept — retrieve all pending concept suggestions
  app.get('/api/admin/vocab-concept-suggestions', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (_req: any, res: Response) => {
    res.json({ suggestions: vocabConceptSuggestions });
  });

  // Get seeding status for all paths in a language
  app.get('/api/admin/textbook/status', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { getUserDb } = await import('./db');
      const { sql: drizzleSql } = await import('drizzle-orm');
      const db = getUserDb();
      const rows = await db.execute(drizzleSql`
        SELECT cp.id as path_id, cp.name as path_name, cp.language,
               COUNT(cl.id) as total_lessons,
               COUNT(tlc.id) as seeded_lessons
        FROM curriculum_paths cp
        LEFT JOIN curriculum_units cu ON cu.curriculum_path_id = cp.id
        LEFT JOIN curriculum_lessons cl ON cl.curriculum_unit_id = cu.id
        LEFT JOIN textbook_lesson_content tlc ON tlc.lesson_id = cl.id
        GROUP BY cp.id, cp.name, cp.language
        ORDER BY cp.language, cp.name
      `);
      res.json({ paths: rows.rows });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

