  // ===== Practice Explorer (Self-Directed Drills) =====

  // Get practice catalog - browse available drills by language/topic
  app.get("/api/practice/catalog", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const { language, tags, difficulty } = req.query;
      
      // Get all drill-type lessons (use 'name' column, not 'lessonTitle')
      const drillLessons = await db
        .select({
          lessonId: curriculumLessons.id,
          lessonName: curriculumLessons.name,
          lessonType: curriculumLessons.lessonType,
          estimatedMinutes: curriculumLessons.estimatedMinutes,
        })
        .from(curriculumLessons)
        .where(eq(curriculumLessons.lessonType, 'drill'))
        .orderBy(curriculumLessons.name);
      
      // Get drill item counts and metadata for each lesson using aggregates
      const catalogItems = await Promise.all(
        drillLessons.map(async (lesson) => {
          // Get accurate count and language using aggregate query
          const countResult = await db
            .select({
              count: sql<number>`count(*)::int`,
              targetLanguage: curriculumDrillItems.targetLanguage,
              avgDifficulty: sql<number>`round(avg(${curriculumDrillItems.difficulty}))::int`,
            })
            .from(curriculumDrillItems)
            .where(eq(curriculumDrillItems.lessonId, lesson.lessonId))
            .groupBy(curriculumDrillItems.targetLanguage)
            .limit(1);
          
          if (countResult.length === 0) return null;
          
          const { count: totalCount, targetLanguage, avgDifficulty } = countResult[0];
          
          // Filter by language if specified
          if (language && targetLanguage !== language) {
            return null;
          }
          
          
          // Filter by difficulty if specified
          if (difficulty) {
            const diffLevel = parseInt(String(difficulty), 10);
            if (!isNaN(diffLevel) && avgDifficulty !== diffLevel) {
              return null;
            }
          }
          // Get sample items for tags/types (limit to 50 for efficiency)
          const sampleItems = await db
            .select({
              itemType: curriculumDrillItems.itemType,
              tags: curriculumDrillItems.tags,
            })
            .from(curriculumDrillItems)
            .where(eq(curriculumDrillItems.lessonId, lesson.lessonId))
            .limit(50);
          
          // Collect unique tags and item types from sample
          const allTags = new Set<string>();
          const allTypes = new Set<string>();
          sampleItems.forEach(item => {
            item.tags?.forEach(t => allTags.add(t));
            allTypes.add(item.itemType);
          });
          
          // Check user's completion status for this lesson (USER database)
          const userProgress = await getUserDb()
            .select()
            .from(selfPracticeSessions)
            .where(
              and(
                eq(selfPracticeSessions.userId, userId),
                eq(selfPracticeSessions.lessonId, lesson.lessonId),
                eq(selfPracticeSessions.status, 'completed')
              )
            )
            .limit(1);
          
          return {
            lessonId: lesson.lessonId,
            lessonTitle: lesson.lessonName,
            targetLanguage: targetLanguage,
            itemCount: totalCount,
            estimatedMinutes: lesson.estimatedMinutes || Math.ceil(Math.min(totalCount, 20) * 0.5),
            tags: Array.from(allTags),
            itemTypes: Array.from(allTypes),
            difficulty: avgDifficulty || 1,
            completed: userProgress.length > 0,
            lastCompletedAt: userProgress[0]?.completedAt || null,
          };
        })
      );
      
      // Filter out null entries (lessons with no matching items)
      const result = catalogItems.filter(Boolean);
      
      // Group by language for easier UI rendering
      const byLanguage: Record<string, typeof result> = {};
      result.forEach(item => {
        if (!item) return;
        if (!byLanguage[item.targetLanguage]) {
          byLanguage[item.targetLanguage] = [];
        }
        byLanguage[item.targetLanguage].push(item);
      });
      
      res.json({
        catalog: result,
        byLanguage,
        totalLessons: result.length,
        languages: Object.keys(byLanguage),
      });
    } catch (error: any) {
      console.error('Error fetching practice catalog:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Start a self-practice session
  app.post("/api/practice/sessions", mutationLimiter, isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const { lessonId } = req.body;
      
      if (!lessonId) {
        return res.status(400).json({ error: "lessonId is required" });
      }
      
      // Get the lesson and its drill items
      const lesson = await storage.getCurriculumLesson(lessonId);
      if (!lesson) {
        return res.status(404).json({ error: "Lesson not found" });
      }
      
      const drillItems = await storage.getDrillItems(lessonId);
      if (drillItems.length === 0) {
        return res.status(400).json({ error: "No drill items found for this lesson" });
      }
      
      // Get targetLanguage from drill items (lessons don't have targetLanguage column)
      const targetLanguage = drillItems[0]?.targetLanguage || 'english';
      
      // Create a new self-practice session
      const [session] = await db
        .insert(selfPracticeSessions)
        .values({
          userId,
          lessonId,
          targetLanguage,
          status: 'in_progress',
          totalItems: drillItems.length,
          completedItems: 0,
          correctItems: 0,
          drillItemIds: drillItems.map(item => item.id),
        })
        .returning();
      
      res.json({
        session,
        lesson: {
          id: lesson.id,
          title: lesson.name,
          targetLanguage,
        },
        drillItems,
      });
    } catch (error: any) {
      console.error('Error starting practice session:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Complete a self-practice session
  app.patch("/api/practice/sessions/:sessionId/complete", mutationLimiter, isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const { sessionId } = req.params;
      const { completedItems, correctItems, averageScore, totalTimeSpentMs } = req.body;
      
      // Get the session and verify ownership (USER database)
      const [session] = await getUserDb()
        .select()
        .from(selfPracticeSessions)
        .where(
          and(
            eq(selfPracticeSessions.id, sessionId),
            eq(selfPracticeSessions.userId, userId)
          )
        );
      
      if (!session) {
        return res.status(404).json({ error: "Session not found" });
      }
      
      if (session.status === 'completed') {
        return res.status(400).json({ error: "Session already completed" });
      }
      
      // Update the session
      const [updated] = await db
        .update(selfPracticeSessions)
        .set({
          status: 'completed',
          completedItems: completedItems ?? session.completedItems,
          correctItems: correctItems ?? session.correctItems,
          averageScore: averageScore ?? session.averageScore,
          totalTimeSpentMs: totalTimeSpentMs ?? session.totalTimeSpentMs,
          completedAt: new Date(),
          updatedAt: new Date(),
        })
        .where(eq(selfPracticeSessions.id, sessionId))
        .returning();
      
      res.json({
        session: updated,
        message: "Practice session completed successfully",
      });
    } catch (error: any) {
      console.error('Error completing practice session:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get user's practice history
  app.get("/api/practice/history", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const { language, limit } = req.query;
      
      let query = getUserDb()
        .select()
        .from(selfPracticeSessions)
        .where(
          and(
            eq(selfPracticeSessions.userId, userId),
            language ? eq(selfPracticeSessions.targetLanguage, language as string) : undefined
          )
        )
        .orderBy(desc(selfPracticeSessions.createdAt))
        .limit(parseInt(limit as string) || 20);
      
      const sessions = await query;
      
      res.json({
        sessions,
        totalSessions: sessions.length,
      });
    } catch (error: any) {
      console.error('Error fetching practice history:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // ===== Lesson Prerequisites (Class Context Only) =====

  // Check if a class lesson's prerequisites are met
  // This only applies to class-based learning; self-directed learners bypass prerequisites
  app.get("/api/class-lessons/:lessonId/prerequisite-status", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const { lessonId } = req.params;
      
      // Get the class lesson
      const lesson = await storage.getClassCurriculumLesson(lessonId);
      if (!lesson) {
        return res.status(404).json({ error: "Lesson not found" });
      }
      
      // If no prerequisite, lesson is unlocked
      if (!lesson.prerequisiteLessonId) {
        return res.json({
          isLocked: false,
          prerequisite: null,
          message: null,
        });
      }
      
      // Get the prerequisite lesson details
      const prerequisiteLesson = await storage.getClassCurriculumLesson(lesson.prerequisiteLessonId);
      if (!prerequisiteLesson) {
        // Prerequisite lesson not found, allow access
        return res.json({
          isLocked: false,
          prerequisite: null,
          message: null,
        });
      }
      
      // Check if prerequisite is a drill lesson
      if (prerequisiteLesson.lessonType === 'drill') {
        // Get the source lesson ID for drill items (drills are stored by curriculum lesson ID)
        const drillLessonId = prerequisiteLesson.sourceLessonId || prerequisiteLesson.id;
        const completion = await storage.checkDrillLessonCompletion(userId, drillLessonId);
        
        if (completion.completed) {
          return res.json({
            isLocked: false,
            prerequisite: {
              id: prerequisiteLesson.id,
              name: prerequisiteLesson.name,
              lessonType: prerequisiteLesson.lessonType,
              completionPercent: completion.completionPercent,
            },
            message: null,
          });
        } else {
          return res.json({
            isLocked: true,
            prerequisite: {
              id: prerequisiteLesson.id,
              name: prerequisiteLesson.name,
              lessonType: prerequisiteLesson.lessonType,
              completionPercent: completion.completionPercent,
              masteredCount: completion.masteredCount,
              totalCount: completion.totalCount,
            },
            message: `Complete "${prerequisiteLesson.name}" first to unlock this lesson`,
          });
        }
      }
      
      // For non-drill prerequisites, check if there's any conversation progress
      // For now, we'll just allow access (conversation completion tracking is more complex)
      return res.json({
        isLocked: false,
        prerequisite: {
          id: prerequisiteLesson.id,
          name: prerequisiteLesson.name,
          lessonType: prerequisiteLesson.lessonType,
        },
        message: null,
      });
      
    } catch (error: any) {
      console.error('Error checking prerequisite status:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // ===== Drill Audio Generation =====

  // Generate audio for all drill items in a lesson (teachers only)
  app.post("/api/drill-audio/generate/:lessonId", mutationLimiter, isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const user = await storage.getUser(userId);
      
      if (!hasTeacherAccess(user?.role)) {
        return res.status(403).json({ error: "Only teachers can generate drill audio" });
      }

      const { lessonId } = req.params;
      const { language, speakingRate, forceRegenerate } = req.body;
      
      if (!language) {
        return res.status(400).json({ error: "language is required" });
      }

      // Use tutorGender as unified voice preference (default to female)
      const voiceGender = user?.tutorGender || 'female';

      const { generateAudioForLesson } = await import('./services/drill-audio-service');
      const results = await generateAudioForLesson(
        lessonId,
        language,
        speakingRate || 0.9,
        forceRegenerate || false,
        voiceGender as 'female' | 'male'
      );
      
      res.json({
        message: "Audio generation complete",
        results,
        successCount: results.filter(r => r.audioUrl).length,
        totalCount: results.length,
      });
    } catch (error: any) {
      console.error('Error generating drill audio:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Pre-warm audio cache for drill lessons (generates both slow and normal speeds)
  // This enables instant playback for students during voice sessions
  app.post("/api/admin/drill-audio/prewarm", mutationLimiter, isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const user = await storage.getUser(userId);
      
      if (!hasTeacherAccess(user?.role)) {
        return res.status(403).json({ error: "Only teachers can pre-warm audio cache" });
      }

      const { lessonId, lessonIds, language, gender = 'female' } = req.body;
      
      if (!language) {
        return res.status(400).json({ error: "language is required" });
      }
      
      const { preWarmLessonAudioCache, preWarmMultipleLessonsAudioCache } = await import('./services/drill-audio-service');
      
      if (lessonIds && Array.isArray(lessonIds)) {
        // Batch pre-warm multiple lessons
        const result = await preWarmMultipleLessonsAudioCache(lessonIds, language, gender);
        res.json({
          message: "Batch pre-warm complete",
          ...result,
        });
      } else if (lessonId) {
        // Single lesson pre-warm
        const result = await preWarmLessonAudioCache(lessonId, language, gender);
        res.json({
          message: "Pre-warm complete",
          ...result,
        });
      } else {
        return res.status(400).json({ error: "Either lessonId or lessonIds is required" });
      }
    } catch (error: any) {
      console.error('Error pre-warming audio cache:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get cached pronunciation audio for Daniela's play_audio tool (Phase 3)
  // Enables instant audio playback during voice sessions
