  // ===== Alden Chat API (Founder Only) =====
  
  app.post("/api/alden/message", isAuthenticated, loadAuthenticatedUser(storage), requireFounder, async (req: any, res: Response) => {
    try {
      const { message, conversationHistory, timezone } = req.body;
      
      if (!message || typeof message !== 'string') {
        return res.status(400).json({ error: 'Message is required' });
      }
      
      const user = req.user;
      const founderName = user?.firstName || 'David';

      // ── Multi-phase autonomous loop ───────────────────────────────────────────
      // Alden can call request_continuation to move through phases automatically.
      // Each phase gets a fresh 10-round budget. Max 5 phases per user message.
      const MAX_PHASES = 5;
      const phases: Array<{ phaseTitle?: string; response: string; toolsUsed: string[] }> = [];
      let runningHistory = [...(conversationHistory || [])];
      let currentPrompt = message;
      let phaseTitle: string | undefined;

      for (let phaseIdx = 0; phaseIdx < MAX_PHASES; phaseIdx++) {
        console.log(`[Alden API] Phase ${phaseIdx + 1}/${MAX_PHASES}: "${currentPrompt.substring(0, 60)}..."`);

        const result = await generateAldenResponse({
          userMessage: currentPrompt,
          conversationHistory: runningHistory,
          founderName,
          timezone,
        });

        phases.push({ phaseTitle, response: result.response, toolsUsed: result.toolsUsed });

        if (!result.continuation) break;

        // Prepare for next phase: append this exchange to history
        runningHistory = [
          ...runningHistory,
          { role: 'user' as const, content: currentPrompt },
          { role: 'model' as const, content: result.response },
        ];
        currentPrompt = result.continuation.nextPrompt;
        phaseTitle = result.continuation.phaseTitle;
        console.log(`[Alden API] Continuation: "${result.continuation.phaseTitle}" → phase ${phaseIdx + 2}`);
      }

      const lastPhase = phases[phases.length - 1];
      const allToolsUsed = phases.flatMap(p => p.toolsUsed);

      // Save conversation to DB before responding — ensures messages persist even if client disconnects
      try {
        const { getSharedDb: _getDb } = await import('./db');
        const { aldenConversations, aldenMessages } = await import('@shared/schema');
        const { and, isNull, gt } = await import('drizzle-orm');
        const _db = _getDb();

        // Find or create an active session (within last 4 hours)
        const cutoff = new Date(Date.now() - 4 * 60 * 60 * 1000);
        const [activeConv] = await _db.select({ id: aldenConversations.id })
          .from(aldenConversations)
          .where(and(isNull(aldenConversations.endedAt), gt(aldenConversations.startedAt, cutoff)))
          .limit(1);

        let convId: string;
        if (activeConv) {
          convId = activeConv.id;
        } else {
          const now = new Date();
          const sessionTitle = 'Session — ' + now.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' });
          const [newConv] = await _db.insert(aldenConversations)
            .values({ title: sessionTitle, startedAt: now })
            .returning({ id: aldenConversations.id });
          convId = newConv.id;
        }

        const speakerRole = req.session?.authProvider === 'ai-browser' ? 'luca' : 'david';
        const messagesToLog = [
          { conversationId: convId, role: speakerRole, content: message, isSignificant: false },
          ...phases.map(p => ({ conversationId: convId, role: 'alden', content: p.response, isSignificant: false })),
        ];
        await _db.insert(aldenMessages).values(messagesToLog);
        console.log(`[Alden Log] Saved ${phases.length} phase(s) to conversation ${convId}`);
      } catch (logErr: any) {
        console.error('[Alden Log] Failed to save conversation:', logErr.message);
      }

      res.json({
        reply: lastPhase.response,
        toolsUsed: allToolsUsed,
        phases: phases.length > 1 ? phases : undefined,
      });
    } catch (error: any) {
      console.error('[Alden API] Error:', error.message);
      res.status(500).json({ error: error.message });
    }
  });

  // Alden priority task — direct channel for Luca/David to fire an immediate task at Alden,
  // optionally across both engines (Anthropic + Gemini) for a dual-perspective review.
  // No cooldown, no polling wait. Result auto-posts to Team Room.
  app.post("/api/alden/priority-task", requireFounderOrAgent, async (req: any, res: Response) => {
    try {
      const { task, context, engines = 'current' } = req.body;
      if (!task || typeof task !== 'string') {
        return res.status(400).json({ error: 'task is required' });
      }

      const { generateAldenResponse, getAldenEngine } = await import('./services/alden-persona-service');
      const { aldenConversations, aldenMessages } = await import('@shared/schema');
      const { isNull, gt, and: _and } = await import('drizzle-orm');
      const _db = getSharedDb();

      const callerLabel = isReplitAgentRequest(req) ? 'luca' : 'david';
      const founderName = callerLabel === 'luca' ? 'Luca' : 'David';

      const userMessage = context
        ? `[PRIORITY TASK]\n\n${task}\n\n[CONTEXT]\n${context}`
        : `[PRIORITY TASK]\n\n${task}`;

      // Determine which engines to run
      const currentEngine = await getAldenEngine();
      const enginesToRun: Array<'anthropic' | 'gemini'> =
        engines === 'both' ? ['anthropic', 'gemini'] :
        engines === 'anthropic' ? ['anthropic'] :
        engines === 'gemini' ? ['gemini'] :
        [currentEngine];

      // Run each engine — in parallel if both
      const engineResults = await Promise.all(
        enginesToRun.map(async (eng) => {
          const result = await generateAldenResponse({
            userMessage,
            founderName,
            engineOverride: eng,
          });
          return {
            engine: eng,
            response: result.response,
            toolsUsed: result.toolsUsed,
            coordinationReadReceipts: result.coordinationReadReceipts ?? [],
          };
        })
      );

      // Persist to alden conversation
      let convId: string;
      try {
        const cutoff = new Date(Date.now() - 4 * 60 * 60 * 1000);
        const [activeConv] = await _db.select({ id: aldenConversations.id })
          .from(aldenConversations)
          .where(_and(isNull(aldenConversations.endedAt), gt(aldenConversations.startedAt, cutoff)))
          .limit(1);
        if (activeConv) {
          convId = activeConv.id;
        } else {
          const now = new Date();
          const title = 'Priority — ' + now.toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
          const [newConv] = await _db.insert(aldenConversations)
            .values({ title, startedAt: now })
            .returning({ id: aldenConversations.id });
          convId = newConv.id;
        }

        const rows: any[] = [
          { conversationId: convId, role: callerLabel, content: userMessage, isSignificant: false },
          ...engineResults.map(r => ({
            conversationId: convId,
            role: enginesToRun.length > 1 ? `alden-${r.engine}` : 'alden',
            content: r.response,
            isSignificant: false,
          })),
        ];
        await _db.insert(aldenMessages).values(rows);
      } catch (logErr: any) {
        console.warn('[Alden Priority] Failed to persist:', logErr.message);
      }

      // Auto-post to Team Room
      try {
        const teamRoomContent = engineResults.length === 1
          ? `**Alden [${engineResults[0].engine}] — Priority Task Response**\n\n${engineResults[0].response}`
          : [
              `**Alden Dual-Engine Review**`,
              ``,
              `**Anthropic:**`,
              engineResults.find(r => r.engine === 'anthropic')?.response ?? '—',
              ``,
              `**Gemini:**`,
              engineResults.find(r => r.engine === 'gemini')?.response ?? '—',
            ].join('\n');

        const rooms = await storage.listTeamRooms(1);
        if (rooms.length) {
          const roomMsg = await storage.createRoomMessage({ roomId: rooms[0].id, speaker: 'Alden', content: teamRoomContent });
          const { emitNewMessage } = await import('./services/team-room-ws-broker');
          emitNewMessage(rooms[0].id, roomMsg);
        }
      } catch (trErr: any) {
        console.warn('[Alden Priority] Team Room post failed:', trErr.message);
      }

      res.json({
        results: engineResults,
        engines: enginesToRun,
        currentEngine,
      });
    } catch (error: any) {
      console.error('[Alden Priority] Error:', error.message);
      res.status(500).json({ error: error.message });
    }
  });

  // Alden session history — load recent messages for the UI
  app.get("/api/alden/session", isAuthenticated, loadAuthenticatedUser(storage), requireFounder, async (req: any, res: Response) => {
    try {
      const { getSharedDb: _getDb2 } = await import('./db');
      const { aldenConversations, aldenMessages } = await import('@shared/schema');
      const { desc, isNull, gt, eq } = await import('drizzle-orm');
      const _db2 = _getDb2();

      // Find the most recent session from the last 24 hours
      const cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000);
      const [session] = await _db2.select()
        .from(aldenConversations)
        .where(gt(aldenConversations.startedAt, cutoff))
        .orderBy(desc(aldenConversations.startedAt))
        .limit(1);

      if (!session) {
        return res.json({ messages: [], sessionId: null, sessionTitle: null });
      }

      const msgs = await _db2.select()
        .from(aldenMessages)
        .where(eq(aldenMessages.conversationId, session.id))
        .orderBy(aldenMessages.createdAt);

      res.json({
        sessionId: session.id,
        sessionTitle: session.title,
        startedAt: session.startedAt,
        messages: msgs.map(m => ({
          id: m.id,
          role: m.role,
          content: m.content,
          createdAt: m.createdAt,
          isSignificant: m.isSignificant,
        })),
      });
    } catch (error: any) {
      console.error('[Alden Session] Fetch error:', error.message);
      res.status(500).json({ error: error.message });
    }
  });

  // GET /api/admin/ai-cost-report — unified AI cost report (in-memory + DB)
  app.get("/api/admin/ai-cost-report", isAuthenticated, loadAuthenticatedUser(storage), requireFounder, async (req: any, res: Response) => {
    try {
      const hours = Math.min(Number(req.query.hours) || 24, 168);
      const since = new Date(Date.now() - hours * 60 * 60 * 1000);
      const env = (req.query.env as string) || 'all';
      const envCondition = env === 'all' ? undefined : eq(voiceSessions.environment, env as any);

      const { costTracker } = await import('./services/cost-tracker');
      const aldenSummary = costTracker.getSummary(hours);
      const aldenText = costTracker.formatForReport(hours);

      // DB historical cost logs — fills the gap after restarts
      const historicalFromDb = await (async () => {
        try {
          const { getSharedDb } = await import('./neon-db');
          const { aiCostLogs } = await import('../shared/schema');
          const dbRows = await getSharedDb()
            .select()
            .from(aiCostLogs)
            .where(gte(aiCostLogs.loggedAt, since.getTime()))
            .orderBy(aiCostLogs.loggedAt);
          // Aggregate by model
          const byModel: Record<string, { calls: number; inputTokens: number; outputTokens: number; costUsd: number }> = {};
          let totalCostUsd = 0;
          for (const row of dbRows) {
            totalCostUsd += row.costUsd ?? 0;
            const m = row.model;
            if (!byModel[m]) byModel[m] = { calls: 0, inputTokens: 0, outputTokens: 0, costUsd: 0 };
            byModel[m].calls++;
            byModel[m].inputTokens += row.inputTokens ?? 0;
            byModel[m].outputTokens += row.outputTokens ?? 0;
            byModel[m].costUsd += row.costUsd ?? 0;
          }
          return { totalCostUsd, callCount: dbRows.length, byModel };
        } catch { return null; }
      })();

      // Lyra last run
      const lyraLastRun = await (async () => {
        try {
          const fs = await import('fs');
          const { join: pathJoin } = await import('path');
          const histFile = pathJoin(process.cwd(), '.local', 'lyra-history.json');
          const hist = JSON.parse(fs.readFileSync(histFile, 'utf8'));
          if (!hist.length) return null;
          const last = hist[hist.length - 1];
          return { timestamp: last.timestamp, ageHours: +((Date.now() - new Date(last.timestamp).getTime()) / 3_600_000).toFixed(1), costUsd: last.costUsd };
        } catch { return null; }
      })();

      // DB: student session economics
      const monDb = getMonitoringDb();
      const conditions: any[] = [gte(voiceSessions.startedAt, since), eq(voiceSessions.isTestSession, false)];
      if (envCondition) conditions.push(envCondition);

      const sessionRows = await monDb.select({
        count: sql<number>`count(*)`,
        activeStudents: sql<number>`count(distinct user_id)`,
        totalDurationSec: sql<number>`coalesce(sum(duration_seconds), 0)`,
        totalTtsChars: sql<number>`coalesce(sum(tts_characters), 0)`,
        totalSttSec: sql<number>`coalesce(sum(stt_seconds), 0)`,
        totalLlmIn: sql<number>`coalesce(sum(llm_input_tokens), 0)`,
        totalLlmOut: sql<number>`coalesce(sum(llm_output_tokens), 0)`,
        totalExchanges: sql<number>`coalesce(sum(exchange_count), 0)`,
      }).from(voiceSessions).where(and(...conditions));

      const s = sessionRows[0] || {};
      const sessions       = Number(s.count          || 0);
      const activeStudents = Number(s.activeStudents  || 0);
      const totalMinutes   = +(Number(s.totalDurationSec || 0) / 60).toFixed(1);
      const ttsChars       = Number(s.totalTtsChars   || 0);
      const sttSec         = Number(s.totalSttSec     || 0);
      const llmIn          = Number(s.totalLlmIn      || 0);
      const llmOut         = Number(s.totalLlmOut     || 0);
      const exchanges      = Number(s.totalExchanges  || 0);
      const llmTokensTracked = llmIn > 0;

      const geminiCost   = llmTokensTracked
        ? (llmIn * 0.075 / 1_000_000) + (llmOut * 0.30 / 1_000_000)
        : exchanges * 0.0005;
      const ttsCost      = (ttsChars / 1000) * 0.015;
      const sttCost      = (sttSec / 60) * 0.0043;
      const studentTotal = geminiCost + ttsCost + sttCost;

      const aldenTotal    = aldenSummary.totalCostUsd;
      const combinedTotal = aldenTotal + studentTotal;

      // Per-student economics
      const costPerStudent = activeStudents > 0 ? studentTotal / activeStudents : null;
      // Extrapolate window cost to monthly (30d) for pricing model
      const windowToMonthFactor = (30 * 24) / hours;
      const monthlyCostPerStudent = costPerStudent != null ? costPerStudent * windowToMonthFactor : null;

      // Pricing model — margin at various price points
      const pricePoints = [4.99, 9.99, 14.99, 19.99, 29.99];
      const pricingModel = monthlyCostPerStudent != null
        ? pricePoints.map(price => ({
            price,
            marginUsd: +(price - monthlyCostPerStudent).toFixed(4),
            marginPct: +((price - monthlyCostPerStudent) / price * 100).toFixed(1),
            breakEvenStudents: aldenTotal > 0 ? Math.ceil(aldenTotal * windowToMonthFactor / (price - monthlyCostPerStudent)) : null,
          }))
        : [];

      // Formatted text report
      const fmt  = (n: number) => `$${n.toFixed(4)}`;
      const fmt2 = (n: number) => `$${n.toFixed(2)}`;
      const fmtK = (n: number) => n > 0 ? `${(n / 1000).toFixed(1)}k` : '0';
      const windowNote = hours < 720 ? ` (extrapolated to 30d)` : '';
      const lines = [
        `=== HoloHola Burn Report (last ${hours}h${env !== 'all' ? `, ${env}` : ''}) ===`,
        `Generated: ${new Date().toUTCString()}`,
        ``,
        `ALDEN STACK (in-memory — since last restart)`,
        aldenSummary.callCount > 0 ? aldenText : `  No calls tracked in memory since last restart`,
        lyraLastRun ? `  Lyra last run: ${lyraLastRun.ageHours}h ago (${fmt(lyraLastRun.costUsd || 0)})` : `  Lyra last run: unknown`,
        `  In-memory subtotal: ${fmt(aldenTotal)}`,
        historicalFromDb
          ? `  DB history (${hours}h): ${historicalFromDb.callCount} call(s) → ${fmt(historicalFromDb.totalCostUsd)} (survives restarts)`
          : `  DB history: unavailable`,
        ``,
        `STUDENT TUTOR SESSIONS (DB — Gemini + TTS + STT)`,
        `  Active students: ${activeStudents} | Sessions: ${sessions} | Minutes: ${totalMinutes}min`,
        `  Gemini: ${llmTokensTracked ? `${fmtK(llmIn)} in / ${fmtK(llmOut)} out (real tokens)` : `${exchanges} exchanges (estimated)`} → ${fmt(geminiCost)}`,
        `  Google TTS: ${fmtK(ttsChars)} chars → ${fmt(ttsCost)}`,
        `  Deepgram STT: ${(sttSec / 60).toFixed(1)}min → ${fmt(sttCost)}`,
        `  Subtotal: ${fmt(studentTotal)}`,
        ``,
        `COMBINED TOTAL: ${fmt(combinedTotal)}`,
        ``,
        `COST PER STUDENT`,
        costPerStudent != null
          ? [
              `  This window (${hours}h): ${fmt(costPerStudent)} / student`,
              `  Monthly estimate${windowNote}: ${fmt2(monthlyCostPerStudent!)} / student`,
            ].join('\n')
          : `  No active students in this window`,
        ``,
        ...(pricingModel.length > 0 ? [
          `PRICING MODEL (monthly, per student)`,
          ...pricingModel.map(p =>
            `  ${fmt2(p.price)}/mo → margin: ${fmt2(p.marginUsd)} (${p.marginPct}%)` +
            (p.breakEvenStudents ? ` | infra break-even: ${p.breakEvenStudents} students` : '')
          ),
        ] : []),
        ``,
        llmTokensTracked ? `  (Gemini tokens from real usage)` : `  (Gemini cost estimated — no real tokens logged yet)`,
      ].join('\n');

      res.json({
        generatedAt: new Date().toISOString(),
        windowHours: hours,
        env,
        aldenStack: {
          inMemory: {
            totalCostUsd: aldenTotal,
            callCount: aldenSummary.callCount,
            byModel: aldenSummary.byModel,
            mostExpensiveModel: aldenSummary.mostExpensiveModel,
            avgCostPerCall: aldenSummary.avgCostPerCall,
          },
          dbHistory: historicalFromDb,
          lyraLastRun,
        },
        studentTutor: {
          sessions,
          activeStudents,
          totalMinutes,
          exchanges,
          geminiInputTokens: llmIn,
          geminiOutputTokens: llmOut,
          geminiTokensTracked: llmTokensTracked,
          geminiCostUsd: geminiCost,
          ttsChars,
          ttsCostUsd: ttsCost,
          sttSeconds: sttSec,
          sttCostUsd: sttCost,
          totalCostUsd: studentTotal,
        },
        perStudent: {
          windowCostUsd: costPerStudent,
          monthlyEstimateUsd: monthlyCostPerStudent,
          windowHours: hours,
          note: hours < 720 ? `Monthly estimate extrapolated from ${hours}h window` : 'Full month of data',
        },
        pricingModel,
        combined: {
          totalCostUsd: combinedTotal,
          aldenStackUsd: aldenTotal,
          studentTutorUsd: studentTotal,
        },
        text: lines,
      });
    } catch (error: any) {
      console.error('[AI Cost Report] Error:', error.message);
      res.status(500).json({ error: error.message });
    }
  });

