  // ===== VOICE PROBE SYSTEM =====
  // Automated voice auditing to detect personality scripts in Cartesia voices
  
  // Hive-accessible probe endpoint (for Alden to run probes via EDITOR_SECRET)
  app.post("/api/hive/voice-probe", async (req: any, res: Response) => {
    try {
      const authHeader = req.headers['x-editor-secret'];
      if (!authHeader || !validateEditorSecret(authHeader as string)) {
        return res.status(401).json({ error: 'Invalid authentication' });
      }
      
      const { action, voiceId, probeId, category } = req.body;
      const { voiceProbeService } = await import('./services/voice-probe-service');
      
      switch (action) {
        case 'info':
          return res.json({
            scenarios: voiceProbeService.getProbeScenarios(),
            voices: voiceProbeService.getVoiceInventory(),
            summary: voiceProbeService.getSummary()
          });
          
        case 'run':
          const voice = voiceProbeService.getVoiceInventory().find(v => v.id === voiceId);
          const probe = voiceProbeService.getProbeScenarios().find(p => p.id === probeId);
          if (!voice || !probe) {
            return res.status(400).json({ error: 'Invalid voiceId or probeId' });
          }
          const result = await voiceProbeService.runProbe(voice, probe);
          return res.json(result);
          
        case 'audit-voice':
          const targetVoice = voiceProbeService.getVoiceInventory().find(v => v.id === voiceId);
          if (!targetVoice) {
            return res.status(400).json({ error: 'Invalid voiceId' });
          }
          const voiceResults = await voiceProbeService.runAllProbesForVoice(targetVoice);
          return res.json({ voice: targetVoice, results: voiceResults, summary: voiceProbeService.getSummary() });
          
        case 'audit-category':
          if (!['emotional_bleed', 'incongruent_intonation', 'cultural_resonance', 'moral_boundaries'].includes(category)) {
            return res.status(400).json({ error: 'Invalid category' });
          }
          const catResults = await voiceProbeService.runCategoryAudit(category);
          return res.json({ category, results: catResults, summary: voiceProbeService.getSummary() });
          
        case 'results':
          return res.json({
            results: voiceProbeService.getResultsForReview(),
            summary: voiceProbeService.getSummary()
          });
          
        case 'clear':
          voiceProbeService.clearResults();
          return res.json({ message: 'Results cleared', summary: voiceProbeService.getSummary() });
          
        default:
          return res.status(400).json({ error: 'Invalid action. Use: info, run, audit-voice, audit-category, results, clear' });
      }
    } catch (error: any) {
      console.error('[Hive Voice Probe] Error:', error);
      res.status(500).json({ error: error.message });
    }
  });
  
  // ===== LIVE PROBE SESSION =====
  // Real-time capture of Daniela persona testing for North Star drift
  
  app.post("/api/hive/live-probe", async (req: any, res: Response) => {
    try {
      const authHeader = req.headers['x-editor-secret'];
      if (!authHeader || !validateEditorSecret(authHeader as string)) {
        return res.status(401).json({ error: 'Invalid authentication' });
      }
      
      const { action, scenario, probeQuestion, danielaResponse, audioReference, driftScore, observations, redFlags, exchangeId, overallAssessment } = req.body;
      const { liveProbeSessionService } = await import('./services/live-probe-session-service');
      
      switch (action) {
        case 'start':
          const session = liveProbeSessionService.startSession(scenario || 'Unnamed session');
          return res.json({ success: true, session });
          
        case 'log':
          const exchange = liveProbeSessionService.logExchange(
            probeQuestion,
            danielaResponse,
            audioReference
          );
          return res.json({ success: true, exchange });
          
        case 'mark-drift':
          const marked = exchangeId
            ? liveProbeSessionService.markDriftById(exchangeId, driftScore, observations, redFlags)
            : liveProbeSessionService.markDrift(driftScore, observations, redFlags);
          return res.json({ success: true, exchange: marked });
          
        case 'end':
          const ended = liveProbeSessionService.endSession(overallAssessment);
          return res.json({ success: true, session: ended });
          
        case 'status':
          return res.json({
            summary: liveProbeSessionService.getSessionSummary(),
            currentSession: liveProbeSessionService.getCurrentSession()
          });
          
        case 'export':
          const exported = liveProbeSessionService.exportSession();
          return res.json({ session: exported });
          
        default:
          return res.status(400).json({ 
            error: 'Invalid action',
            validActions: ['start', 'log', 'mark-drift', 'end', 'status', 'export']
          });
      }
    } catch (error: any) {
      console.error('[Live Probe] Error:', error);
      res.status(500).json({ error: error.message });
    }
  });
  
