  // ===== Cross-Student Pattern Synthesis (Teachers) =====
  // Get pronunciation patterns across students in a class
  app.get("/api/teacher/classes/:classId/pronunciation-patterns", isAuthenticated, async (req: any, res: Response) => {
    try {
      const teacherId = req.user?.claims?.sub;
      const { classId } = req.params;
      const user = await storage.getUser(teacherId);
      
      if (!hasTeacherAccess(user?.role)) {
        return res.status(403).json({ error: "Teacher access required" });
      }
      
      // Verify teacher owns this class (or is admin)
      const teacherClass = await storage.getTeacherClass(classId);
      if (!teacherClass) {
        return res.status(404).json({ error: "Class not found" });
      }
      
      if (user?.role !== 'admin' && teacherClass.teacherId !== teacherId) {
        return res.status(403).json({ error: "Not authorized for this class" });
      }
      
      // Get all students in the class
      const enrollments = await getUserDb().select({
        userId: classEnrollments.studentId,
      })
      .from(classEnrollments)
      .where(eq(classEnrollments.classId, classId));
      
      const studentIds = enrollments.map(e => e.userId);
      
      if (studentIds.length === 0) {
        return res.json({
          patterns: [],
          studentCount: 0,
          language: teacherClass.language,
        });
      }
      
      // Use PhonemeAnalyticsService for confidence-based severity metrics
      const { phonemeAnalyticsService } = await import("./services/phoneme-analytics-service");
      const patterns = await phonemeAnalyticsService.getClassPhonemePatterns(studentIds, teacherClass.language);
      
      res.json({
        patterns,
        studentCount: studentIds.length,
        language: teacherClass.language,
      });
    } catch (error: any) {
      console.error('[Pattern Synthesis] Error:', error);
      res.status(500).json({ error: error.message });
    }
  });
  
