  // Get growth memories for review (Founder Only)
  app.get("/api/admin/growth-memories", isAuthenticated, loadAuthenticatedUser(storage), requireFounder, async (req: any, res: Response) => {
    try {
      const { reviewStatus, migrationType, limit = '50', view } = req.query;

      // Resonance Shelf view: memories that have confirmed apply-event outcomes
      if (view === 'resonance') {
        const resonanceLimit = parseInt(limit as string) || 50;
        const memories = await getSharedDb()
          .select()
          .from(danielaGrowthMemories)
          .where(gte(danielaGrowthMemories.timesApplied, 1))
          .orderBy(sql`COALESCE(${danielaGrowthMemories.successRate}, 0) * ${danielaGrowthMemories.timesApplied} DESC`)
          .limit(resonanceLimit);

        const countResult = await getSharedDb()
          .select({ count: sql<number>`COUNT(*)::int` })
          .from(danielaGrowthMemories)
          .where(gte(danielaGrowthMemories.timesApplied, 1));

        return res.json({ memories, total: countResult[0]?.count || 0 });
      }

      let query = getSharedDb().select().from(danielaGrowthMemories);
      
      const conditions: any[] = [];
      
      if (reviewStatus && reviewStatus !== 'all') {
        conditions.push(eq(danielaGrowthMemories.reviewStatus, reviewStatus));
      }
      
      if (migrationType === 'historical') {
        conditions.push(sql`metadata->>'migrationType' = 'historical'`);
      }
      
      if (conditions.length > 0) {
        query = query.where(and(...conditions)) as any;
      }
      
      const memories = await query
        .orderBy(desc(danielaGrowthMemories.createdAt))
        .limit(parseInt(limit as string));
      
      // Get total count
      let countQuery = getSharedDb().select({ count: sql<number>`COUNT(*)::int` }).from(danielaGrowthMemories);
      if (conditions.length > 0) {
        countQuery = countQuery.where(and(...conditions)) as any;
      }
      const countResult = await countQuery;
      
      res.json({
        memories,
        total: countResult[0]?.count || 0,
      });
    } catch (error: any) {
      console.error('[Growth Memories] Fetch error:', error);
      res.status(500).json({ error: error.message });
    }
  });
  
  // Update a growth memory (approve/reject) - Founder Only
  // Strict schema validation - only allow reviewStatus and validated fields
  const growthMemoryUpdateSchema = z.object({
    reviewStatus: z.enum(['pending', 'approved_founder', 'approved_auto', 'rejected', 'needs_revision']).optional(),
    validated: z.boolean().optional(),
  }).strict();
  
  app.patch("/api/admin/growth-memories/:id", isAuthenticated, loadAuthenticatedUser(storage), requireFounder, async (req: any, res: Response) => {
    try {
      const { id } = req.params;
      
      // Validate request body with strict schema
      const parseResult = growthMemoryUpdateSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ 
          error: "Invalid request body",
          details: parseResult.error.flatten().fieldErrors 
        });
      }
      
      const { reviewStatus, validated } = parseResult.data;
      
      // Only update allowed fields
      const updates: { reviewStatus?: string; validated?: boolean; committedToNeuralNetwork?: boolean } = {};
      if (reviewStatus !== undefined) updates.reviewStatus = reviewStatus;
      if (validated !== undefined) updates.validated = validated;
      
      // Auto-commit to neural network when approved (either via reviewStatus or validated flag)
      if (reviewStatus === 'approved_founder' || reviewStatus === 'approved_auto' || validated === true) {
        updates.committedToNeuralNetwork = true;
      }
      
      if (Object.keys(updates).length === 0) {
        return res.status(400).json({ error: "No valid fields to update" });
      }
      
      await getSharedDb().update(danielaGrowthMemories)
        .set(updates as any)
        .where(eq(danielaGrowthMemories.id, id));
      
      res.json({ success: true });
    } catch (error: any) {
      console.error('[Growth Memories] Update error:', error);
      res.status(500).json({ error: error.message });
    }
  });
  
