  // Apply a previously previewed replacement — save to media_files and delete the old entry
  app.post("/api/admin/media/apply-refetch-preview", isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const adminId = getRequestUserId(req)!;
      const { oldId, previewUrl, word, language, searchQuery, title } = req.body;
      if (!previewUrl || !word || !language) {
        return res.status(400).json({ error: "previewUrl, word, and language are required" });
      }
      const primaryKey = `vocab_${language}_${word.toLowerCase().replace(/\s+/g, '_')}`;
      const newFile = await storage.cacheImage({
        url: previewUrl,
        filename: `vocab_ai_${primaryKey}_${Date.now()}.jpg`,
        mimeType: 'image/jpeg',
        mediaType: 'image',
        imageSource: 'ai_generated',
        searchQuery: searchQuery || primaryKey,
        uploadedBy: adminId,
        title: title || word,
        description: word,
        tags: ['vocabulary', 'ai_generated', language],
        language,
        targetWord: word,
      });
      if (oldId) {
        try { await storage.deleteMediaFile(oldId); } catch (e: any) {
          console.warn('[AdminMedia] Old entry cleanup skipped:', e.message);
        }
      }
      await storage.logAdminAction({
        actorId: adminId,
        action: 'apply_preview_refetch',
        targetType: 'media_file',
        targetId: newFile.id,
        metadata: { word, language, oldId, previewUrl },
      });
      res.json({ success: true, newId: newFile.id, imageUrl: previewUrl });
    } catch (error: any) {
      console.error('[AdminMedia] apply-refetch-preview error:', error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/admin/media/generate-illustration", isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const adminId = getRequestUserId(req)!;
      const { concept, style } = req.body;
      if (!concept?.trim()) {
        return res.status(400).json({ error: "Concept is required" });
      }
      const { generateVisual, shouldCacheVisualResult } = await import('./services/visual-content-service');
      const { archiveImageToPermanentStorage } = await import('./services/image-storage');
      const crypto = await import('crypto');
      const result = await generateVisual(
        concept,
        'image',
        {},
        style || 'warm, friendly illustration, educational'
      );
      if (!shouldCacheVisualResult(result)) {
        return res.status(502).json({ error: 'Image generation returned a placeholder; asset was not cached' });
      }
      const hash = crypto.createHash('md5').update('admin_visual_' + concept + Date.now()).digest('hex');
      const permanentUrl = await archiveImageToPermanentStorage(result.imageUrl, `${hash}.jpg`);
      const mediaFile = await storage.cacheImage({
        mediaType: 'image',
        url: permanentUrl,
        filename: `illustration-${hash}.jpg`,
        mimeType: 'image/jpeg',
        imageSource: 'ai_generated',
        promptHash: hash,
        title: concept,
        description: result.altText,
        tags: result.semanticTags,
        language: 'spanish',
      });
      await storage.logAdminAction({
        actorId: adminId,
        action: 'generate_illustration',
        targetType: 'media_file',
        targetId: mediaFile.id,
        metadata: { concept, style, conceptAlignment: result.conceptAlignment, semanticTags: result.semanticTags },
      });
      res.json({
        success: true,
        imageUrl: permanentUrl,
        altText: result.altText,
        semanticTags: result.semanticTags,
        accessibilityDescription: result.accessibilityDescription,
        conceptAlignment: result.conceptAlignment,
        mediaFileId: mediaFile.id,
      });
    } catch (error: any) {
      console.error('Error generating illustration:', error);
      res.status(500).json({ error: error.message });
    }
  });

