  // List prop room asset images (from visual_assets)
  // ─── Image Engine Test ────────────────────────────────────────────────────
  // POST /api/admin/image-engine-test
  // Generates ONE image with the specified engine and returns it as a data URL.
  // The frontend fires N parallel requests (one per desired run) and renders them
  // as they land, so results fill in incrementally.
  app.post('/api/admin/image-engine-test', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    try {
      const { engine, concept, type = 'scene', referenceImageB64, referenceImageMimeType, variationIndex = 0, extractionMode = 'character', styleDescriptionOverride } = req.body as {
        engine: string;
        concept: string;
        type?: 'scene' | 'prop';
        referenceImageB64?: string;
        referenceImageMimeType?: string;
        variationIndex?: number;
        extractionMode?: 'character' | 'environment';
        styleDescriptionOverride?: string;
      };
      if (!engine || !concept) {
        return res.status(400).json({ error: 'engine and concept are required' });
      }
      const { runEngineTest } = await import('./services/image-engine-test');
      const reference = referenceImageB64 && referenceImageMimeType
        ? { b64: referenceImageB64, mimeType: referenceImageMimeType }
        : undefined;
      const result = await runEngineTest(engine, concept, type, reference, variationIndex, extractionMode, styleDescriptionOverride);
      res.json(result);
    } catch (error: any) {
      console.error('[ImageEngineTest] error:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // ─── Image Engine Test — fetch a cached Daniela image as base64 reference ──
  // Looks up the cached "hola" (Spanish) image which always features Daniela,
  // fetches the URL, and returns it as base64 for use as a reference image in
  // Gemini Flash multimodal generation.
  app.get('/api/admin/image-engine-test/daniela-reference', isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (_req: any, res: Response) => {
    try {
      const candidateKeys = [
        'vocab_spanish_hola',
        'vocab_spanish_buenos dias',
        'vocab_spanish_encantada',
        'vocab_spanish_mas o menos',
      ];
      let foundUrl: string | null = null;
      let foundKey: string | null = null;
      for (const key of candidateKeys) {
        const cached = await storage.getCachedStockImage(key);
        if (cached?.url) { foundUrl = cached.url; foundKey = key; break; }
      }
      if (!foundUrl || !foundKey) {
        return res.status(404).json({ error: 'No cached Daniela image found. Seed the greeting images first.' });
      }

      // URLs are stored as app-relative paths like /api/media/ai-image/<filename>
      // — they are NOT fetchable via HTTP. Use the image-storage service to read
      // directly from GCS (same path that serveStoredAiImage uses successfully).
      const AI_IMAGE_PREFIX = '/api/media/ai-image/';
      if (!foundUrl.startsWith(AI_IMAGE_PREFIX)) {
        return res.status(400).json({ error: `Unexpected URL format: ${foundUrl}` });
      }
      const filename = foundUrl.slice(AI_IMAGE_PREFIX.length);

      const { downloadAiImageAsBuffer } = await import('./services/image-storage');
      const result = await downloadAiImageAsBuffer(filename);
      if (!result) {
        return res.status(404).json({ error: `Image not found in storage: ${filename}` });
      }

      const b64 = result.buffer.toString('base64');
      res.json({ b64, mimeType: result.contentType, sourceKey: foundKey, url: foundUrl });
    } catch (error: any) {
      console.error('[ImageEngineTest] daniela-reference error:', error);
      res.status(500).json({ error: error.message });
    }
  });

