  // Voice message to Support Agent (transcribe + respond)
  // Zod schema for voice message validation
  const voiceMessageSchema = z.object({
    ticketId: z.string().min(1, 'Ticket ID is required'),
    category: z.enum(['technical', 'account', 'billing', 'content', 'feedback', 'other']).optional().default('other'),
    mode: z.enum(['support', 'drill']).optional().default('support'),
    drillContext: z.string().optional(),
  });
  
  app.post("/api/support/voice-message", isAuthenticated, loadAuthenticatedUser(storage), upload.single('audio'), async (req: any, res: Response) => {
    try {
      const userId = getRequestUserId(req);
      const audioFile = req.file;
      
      if (!audioFile) {
        return res.status(400).json({ error: 'Audio file is required' });
      }
      
      // Validate request body with Zod
      const parseResult = voiceMessageSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ error: parseResult.error.issues[0].message });
      }
      
      const { ticketId, category, mode, drillContext: drillContextStr } = parseResult.data;
      
      // TEMPORARY: Disable drill mode until proper drill session system is implemented
      // This prevents unauthenticated uploads via drill-mode path
      if (mode === 'drill') {
        return res.status(501).json({ 
          error: 'Drill mode voice is not yet available. Please use the text-based drill exercises.',
          code: 'DRILL_MODE_DISABLED'
        });
      }
      
      // Parse drillContext if sent as JSON string (guard against empty strings)
      let drillContext: { lessonId?: string; exerciseType?: string; prompt?: string } | undefined;
      if (drillContextStr && drillContextStr.trim().length > 0) {
        try {
          drillContext = JSON.parse(drillContextStr);
        } catch (e: any) {
          // Ignore parse errors - treat as no drill context
        }
      }
      
      // Verify ticket ownership (required for all modes)
      const ticket = await storage.getSupportTicket(ticketId);
      if (!ticket) {
        return res.status(404).json({ error: 'Ticket not found' });
      }
      if (ticket.userId !== userId) {
        const user = await storage.getUser(userId);
        if (!user || ((user.role as string) !== 'admin' && (user.role as string) !== 'super_admin' && (user.role as string) !== 'support_agent')) {
          return res.status(403).json({ error: 'Not authorized to message this ticket' });
        }
      }
      
      // Transcribe using Deepgram prerecorded API
      let transcript = '';
      try {
        const response = await getDeepgramClient().listen.prerecorded.transcribeFile(
          audioFile.buffer,
          {
            model: 'nova-2',
            language: 'multi',
            smart_format: true,
            punctuate: true,
            mimetype: 'audio/webm',
            detect_language: true,
          }
        );
        
        transcript = response.result?.results?.channels?.[0]?.alternatives?.[0]?.transcript || '';
      } catch (sttError) {
        console.error('[API] STT error:', sttError);
        return res.status(500).json({ error: 'Failed to transcribe audio' });
      }
      
      if (!transcript || transcript.trim().length === 0) {
        return res.json({ transcript: '', reply: "I couldn't hear what you said. Could you please try again?" });
      }
      
      // Store the user message using storage (reliable persistence)
      await storage.addSupportMessage({
        ticketId,
        senderType: 'user',
        senderId: userId,
        content: transcript,
      });
      
      // Get AI-powered reply from Sofia
      let reply: string;
      let shouldReturnToDaniela = false;
      let knowledgeUsed: string | undefined;
      
      if ((mode as string) === 'drill' && drillContext) {
        reply = `Great job working on this ${drillContext.exerciseType || 'exercise'}! Keep practicing.`;
      } else {
        const user = await storage.getUser(userId);
        
        // Detect dev mode - developers, admins, founder, and support agents get technical support
        const devRoles = ['developer', 'admin', 'super_admin', 'founder', 'support_agent'];
        const isDevUser = (user?.role && devRoles.includes(user.role)) ||
          user?.email === (process.env.FOUNDER_EMAIL || 'davidwmcintosh@gmail.com');
        const supportMode = isDevUser ? 'dev' : 'user';
        
        // Voice diagnostics for ALL users — Sofia uses them internally for smart diagnosis
        const voiceDiagnosticsContext = voiceDiagnostics.getSupportDiagnostics();
        
        const result = await supportPersonaService.generateResponse({
          ticketId,
          userMessage: transcript,
          userName: user?.firstName || undefined,
          deviceInfo: (ticket as any).deviceInfo as { browser?: string; os?: string; device?: string } | undefined,
          handoffContext: ticket.handoffReason ? {
            fromDaniela: ticket.handoffReason.includes('Daniela'),
            learningTopic: ticket.handoffReason,
          } : undefined,
          mode: supportMode,
          voiceDiagnostics: voiceDiagnosticsContext,
        });
        
        reply = result.response;
        shouldReturnToDaniela = result.shouldReturnToDaniela;
        knowledgeUsed = result.knowledgeUsed;
      }
      
      // Store the support response using storage (reliable persistence)
      await storage.addSupportMessage({
        ticketId,
        senderType: 'support',
        content: reply,
      });
      
      res.json({ transcript, reply, shouldReturnToDaniela, knowledgeUsed });
    } catch (error: any) {
      console.error('[API] Error processing voice message:', error);
      res.status(500).json({ error: error.message });
    }
  });
  
