  // Admin: Gemini Live voice audition — user sends mic PCM, server opens real GL session (3.1 or 3.5), returns WAV
  app.post("/api/admin/gl-audition", isAuthenticated, loadAuthenticatedUser(storage), requireRole('admin'), async (req: any, res: Response) => {
    const { audio, languageCode, voiceId, model } = req.body;
    if (!audio) return res.status(400).json({ error: 'audio (base64 PCM16 @ 16kHz) required' });

    const VALID_VOICES = new Set([
      'Aoede','Kore','Leda','Zephyr','Puck','Charon','Fenrir','Orus',
      'Achernar','Autonoe','Callirrhoe','Despina','Erinome','Laomedeia',
      'Pulcherrima','Sulafat','Vindemiatrix','Achird','Algenib','Algieba',
      'Alnilam','Enceladus','Gacrux','Iapetus','Rasalgethi','Sadachbia',
      'Sadaltager','Schedar','Umbriel','Zubenelgenubi',
    ]);
    const VALID_GL_MODELS = new Set([
      'gemini-3.1-flash-live-preview',
      'gemini-2.5-flash-native-audio-preview-12-2025',
    ]);
    const voice = VALID_VOICES.has(voiceId) ? voiceId : 'Aoede';
    const langCode = languageCode || 'es-ES';
    const MODEL = VALID_GL_MODELS.has(model) ? model : (process.env.GEMINI_LIVE_MODEL || 'gemini-3.1-flash-live-preview');
    console.log(`[GL Audition] model: ${MODEL}, voice: ${voice}, langCode: ${langCode}`);

    // Build a language-aware system instruction so the model responds in the
    // correct language (and hopefully with the correct accent) during audition.
    const LANG_CODE_TO_INSTRUCTION: Record<string, string> = {
      'en-US': 'Respond in English (American accent).',
      'en-GB': 'Respond in English with a British accent.',
      'en-AU': 'Respond in English with an Australian accent.',
      'en-IN': 'Respond in English with an Indian accent.',
      'en-CA': 'Respond in English with a Canadian accent.',
      'en-ZA': 'Respond in English with a South African accent.',
      'es-ES': 'Responde en español con acento de España (castellano).',
      'es-MX': 'Responde en español con acento mexicano.',
      'es-CO': 'Responde en español con acento colombiano.',
      'es-AR': 'Responde en español con acento argentino.',
      'es-CL': 'Responde en español con acento chileno.',
      'es-PE': 'Responde en español con acento peruano.',
      'es-US': 'Responde en español latino.',
      'fr-FR': 'Réponds en français avec un accent de France.',
      'fr-CA': 'Réponds en français québécois.',
      'fr-BE': 'Réponds en français belge.',
      'fr-CH': 'Réponds en français suisse.',
      'de-DE': 'Antworte auf Deutsch mit deutschem Akzent.',
      'de-AT': 'Antworte auf Österreichischem Deutsch.',
      'de-CH': 'Antworte auf Schweizerdeutsch.',
      'it-IT': 'Rispondi in italiano con accento italiano.',
      'it-CH': 'Rispondi in italiano svizzero.',
      'pt-BR': 'Responda em português brasileiro.',
      'pt-PT': 'Responda em português europeu.',
      'ja-JP': '日本語で返答してください。',
      'zh-CN': '请用普通话（简体中文）回答。',
      'zh-TW': '請用國語（繁體中文）回答。',
      'ko-KR': '한국어로 대답해주세요.',
      'he-IL': 'ענה בעברית.',
    };
    const langInstruction = LANG_CODE_TO_INSTRUCTION[langCode] || `Respond in the language matching locale ${langCode}.`;
    const auditionSystemInstruction = `You are a friendly language tutor demonstrating your voice. ${langInstruction} The user will say something brief — respond warmly in one or two sentences.`;

    try {
      const { GoogleGenAI, Modality } = await import('@google/genai');
      const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY || '' });

      // Decode the base64 PCM16 audio and append 3s of silence so the default
      // VAD (silenceDurationMs: 800ms) reliably fires without any protocol changes.
      const audioBytes = Buffer.from(audio, 'base64');
      const SILENCE_SECONDS = 3;
      const SILENCE_BYTES = 16000 * SILENCE_SECONDS * 2; // 16kHz, 16-bit = 2 bytes/sample
      const paddedAudio = Buffer.concat([audioBytes, Buffer.alloc(SILENCE_BYTES, 0)]);
      const paddedBase64 = paddedAudio.toString('base64');

      const responseChunks: Buffer[] = [];
      let glSession: any = null;
      let audioSent = false;

      const sendAudio = (s: any) => {
        if (audioSent) return;
        audioSent = true;
        console.log(`[GL Audition] Sending audio — voice: ${voice}, langCode: ${langCode}, audioBytes: ${audioBytes.length}, paddedBytes: ${paddedAudio.length}`);
        s.sendRealtimeInput({ audio: { data: paddedBase64, mimeType: 'audio/pcm;rate=16000' } });
      };

      await new Promise<void>((resolve, reject) => {
        const TIMEOUT_MS = 30000;
        const timer = setTimeout(() => {
          try { glSession?.close(); } catch {}
          if (responseChunks.length > 0) resolve();
          else reject(new Error('GL audition timed out — no audio response received'));
        }, TIMEOUT_MS);

        const finish = (err?: Error) => {
          clearTimeout(timer);
          try { glSession?.close(); } catch {}
          err ? reject(err) : resolve();
        };

        ai.live.connect({
          model: MODEL,
          config: {
            systemInstruction: auditionSystemInstruction,
            responseModalities: [Modality.AUDIO],
            speechConfig: {
              languageCode: langCode,
              voiceConfig: { prebuiltVoiceConfig: { voiceName: voice } },
            },
          },
          callbacks: {
            onopen: () => { if (glSession) sendAudio(glSession); },
            onmessage: (msg: any) => {
              // Collect inline audio parts from modelTurn
              for (const part of msg.serverContent?.modelTurn?.parts ?? []) {
                if (part.inlineData?.data && part.inlineData?.mimeType?.includes('audio')) {
                  responseChunks.push(Buffer.from(part.inlineData.data, 'base64'));
                }
              }
              // 3.1 uses generationComplete; 3.5 may use turnComplete — handle both
              if (msg.serverContent?.turnComplete || msg.serverContent?.generationComplete) {
                if (responseChunks.length > 0) finish();
              }
            },
            onerror: (e: any) => {
              console.error('[GL Audition] onerror:', e?.message ?? e?.code ?? String(e));
              finish(new Error(e?.message ?? 'GL error'));
            },
            onclose: (event: any) => {
              const code = event?.code ?? '?';
              const reason = event?.reason || '(no reason)';
              console.log(`[GL Audition] onclose — code: ${code}, reason: ${reason}, chunks: ${responseChunks.length}`);
              if (responseChunks.length > 0) finish();
              else finish(new Error(`GL session closed (code: ${code}, reason: ${reason})`));
            },
          },
        }).then((s: any) => {
          glSession = s;
          sendAudio(s); // also covers the case where onopen fired before this .then()
        }).catch((e: any) => finish(e instanceof Error ? e : new Error(String(e))));
      });

      // Build WAV: PCM16 LE at 24kHz mono (GL output sample rate)
      const pcm = Buffer.concat(responseChunks);
      const SR = 24000, CH = 1, BITS = 16;
      const byteRate = SR * CH * (BITS / 8);
      const blockAlign = CH * (BITS / 8);
      const hdr = Buffer.alloc(44);
      hdr.write('RIFF', 0);        hdr.writeUInt32LE(36 + pcm.length, 4);
      hdr.write('WAVE', 8);        hdr.write('fmt ', 12);
      hdr.writeUInt32LE(16, 16);   hdr.writeUInt16LE(1, 20);
      hdr.writeUInt16LE(CH, 22);   hdr.writeUInt32LE(SR, 24);
      hdr.writeUInt32LE(byteRate, 28); hdr.writeUInt16LE(blockAlign, 32);
      hdr.writeUInt16LE(BITS, 34); hdr.write('data', 36);
      hdr.writeUInt32LE(pcm.length, 40);

      console.log(`[GL Audition] Returning ${pcm.length} bytes PCM (${(pcm.length / (SR * 2)).toFixed(1)}s audio)`);
      res.setHeader('Content-Type', 'audio/wav');
      res.send(Buffer.concat([hdr, pcm]));
    } catch (error: any) {
      console.error('[GL Audition] Error:', error.message);
      if (!res.headersSent) res.status(500).json({ error: error.message || 'GL audition failed' });
    }
  });

