  // GET /api/debug/voice-prompt — returns the exact system prompt injected into a founder voice session.
  // Agent-only endpoint (requireAgentToken). Use this to inspect what Daniela actually receives in voice
  // mode, audit prompt size, and feed it to consult-daniela's Voice Pipeline Mode for meta-conversation.
  // Query params: language (default: english), founderName (default: David)
  // NOTE: Founder mode is language-agnostic — David can invoke it from any of the 9 language tutors.
  // The language param here reflects whatever session language David is in at the time.
  // Default is 'english' since most founder product discussions happen in English.
  app.get("/api/debug/voice-prompt", requireAgentToken, async (req: any, res: any) => {
    try {
      const language = (req.query.language as string) || 'english';
      const founderName = (req.query.founderName as string) || 'David';

      // Fetch Daniela's self-affirmation notes (notes she wrote to herself in Honesty Mode)
      let selfAffirmationNotes: { title: string; content: string; createdAt: Date }[] = [];
      try {
        const rawNotes = await storage.getDanielaNotes({ noteType: 'self_affirmation' as any, includeArchived: false, limit: 5 });
        selfAffirmationNotes = rawNotes.map((n: any) => ({
          title: n.title || '',
          content: n.content || '',
          createdAt: n.createdAt || new Date(),
        }));
      } catch (_e) {}

      // Build a minimal CompassContext with real data from the DB so synthesis framing fires.
      // Fetches David's most recent self-reflection — that's all we need for the opening field.
      let debugCompassContext: import('@shared/schema').CompassContext | null = null;
      try {
        const [david] = await db
          .select({ id: users.id })
          .from(users)
          .where(eq(users.email, 'davidwmcintosh@gmail.com'))
          .limit(1);
        if (david) {
          const [latestReflection] = await db
            .select({ content: danielaSelfReflections.content })
            .from(danielaSelfReflections)
            .where(and(
              eq(danielaSelfReflections.userId, david.id),
              excludesOperationalMemories(danielaSelfReflections.tags),
            ))
            .orderBy(desc(danielaSelfReflections.createdAt))
            .limit(1);
          const now = new Date();
          debugCompassContext = {
            studentName: founderName,
            studentGoals: null,
            studentInterests: null,
            lastSessionSummary: null,
            studentActflLevel: null,
            studentActflAssessed: false,
            studentActflSource: null,
            sessionDurationMinutes: 30,
            warmthBufferMinutes: 5,
            mustHaveTopics: [],
            niceToHaveTopics: [],
            currentTimeUTC: now.toISOString(),
            currentTimeFormatted: now.toLocaleTimeString('en-US', { timeZone: 'UTC', hour: '2-digit', minute: '2-digit' }) + ' UTC',
            elapsedSeconds: 0,
            remainingSeconds: 1800,
            topicsCovered: [],
            topicsPending: [],
            isOnTrack: true,
            parkingLotItems: [],
            danielaSelfReflection: latestReflection?.content ?? null,
          };
        }
      } catch (_e) {}

      const prompt = createSystemPrompt(
        language,           // language
        'intermediate',     // difficulty
        0,                  // messageCount
        false,              // isVoiceMode (legacy)
        null,               // topic
        [],                 // previousConversations
        'english',          // nativeLanguage
        undefined,          // dueVocabulary
        undefined,          // sessionVocabulary
        null,               // actflLevel
        false,              // isResuming
        0,                  // totalMessageCount
        'warm',             // tutorPersonality
        3,                  // tutorExpressiveness
        true,               // isStreamingVoiceMode ← the key flag
        null,               // curriculumContext
        'flexible_goals',   // tutorFreedomLevel
        null,               // targetActflLevel
        debugCompassContext,// compassContext ← real self-reflection injected
        true,               // isFounderMode ← the other key flag
        founderName,        // founderName
        false,              // isRawHonestyMode
        'Daniela',          // tutorName
        'female',           // tutorGender
        [],                 // tutorDirectory
        null,               // studentTimezone
        'founder',          // userRole
        'product_discussion', // sessionIntent
        null,               // editorConversationContext
        null,               // surgeryContext
        null,               // studentMemoryContext
        founderName,        // studentDisplayName
        null,               // predictiveTeachingContext
        null,               // tutorPersona
        null,               // studentSnapshotContext
        true,               // useFunctionCalling
        selfAffirmationNotes
      );

      const GL_CAP = 40_000;
      const charCount = prompt.length;
      const richBudget = GL_CAP - charCount;

      res.json({
        charCount,
        glCap: GL_CAP,
        richSectionBudget: richBudget,
        percentUsed: Math.round((charCount / GL_CAP) * 100),
        headroom: richBudget > 0 ? `${richBudget} chars available for identity/memory sections` : `OVER CAP by ${Math.abs(richBudget)} chars`,
        prompt,
      });
    } catch (err: any) {
      console.error('[DebugVoicePrompt] Error:', err);
      res.status(500).json({ error: err.message });
    }
  });

  // POST /api/agent/dialogue/trigger — kick off an Agent↔Daniela architectural dialogue
