  // ── Luca ↔ David chat ──────────────────────────────────────────────────────
  // GET  /api/admin/luca/chat  — fetch recent David↔Luca exchange history
  // POST /api/admin/luca/chat  — David sends a message; Luca responds with Daniela context
  // POST /api/admin/luca/relay-to-daniela — queue a Luca message for delivery into Daniela's session

  app.get("/api/admin/luca/chat", loadAuthenticatedUser(storage), requireFounderOrAgent, async (_req: any, res: Response) => {
    try {
      const { agentNotes } = await import('@shared/schema');
      const { desc, and, or, eq, like } = await import('drizzle-orm');
      const notes = await getUserDb()
        .select()
        .from(agentNotes)
        .where(
          and(
            like(agentNotes.subject, '[CHAT]%'),
            or(eq(agentNotes.fromAgent, 'david'), eq(agentNotes.fromAgent, 'luca'))
          )
        )
        .orderBy(desc(agentNotes.createdAt))
        .limit(40);

      const messages = notes.reverse().map((n: any) => ({
        id: n.id,
        role: n.fromAgent === 'luca' ? 'luca' : 'david',
        content: n.body,
        createdAt: n.createdAt instanceof Date ? n.createdAt.toISOString() : (n.createdAt ?? new Date().toISOString()),
        isProactive: typeof n.subject === 'string' && n.subject.startsWith('[CHAT][AUTO]'),
      }));
      res.json({ messages });
    } catch (error: any) {
      console.error('[Luca Chat] GET error:', error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/admin/luca/chat", loadAuthenticatedUser(storage), requireFounderOrAgent, lucaChatPostHandler);

  app.post("/api/admin/luca/relay-to-daniela", loadAuthenticatedUser(storage), requireFounder, async (req: any, res: Response) => {
    try {
      const { message, sessionId } = req.body as { message: string; sessionId?: string | null };
      if (!message?.trim()) return res.status(400).json({ error: 'message is required' });

      const trimmed = message.trim();

      // 1. Attempt live injection into the active GL session.
      // When a sessionId is supplied, require an exact conversation match — never fall back to
      // an arbitrary active session, which could deliver private content to the wrong student.
      // When no sessionId is given, only inject if exactly one session is currently active;
      // with 0 or ≥2 sessions the target is ambiguous and we queue instead of guessing.
      const { getActiveGlSessionByConversation, getAnyActiveGlSession, getActiveGlSessionCount } = await import('./services/gemini-live-session');
      const glSession = sessionId
        ? getActiveGlSessionByConversation(sessionId)
        : getActiveGlSessionCount() === 1 ? getAnyActiveGlSession() : null;

      let injected = false;
      if (glSession) {
        injected = glSession.injectAgentRelay('Luca', trimmed);
        if (injected) {
          console.log(`[Luca Relay] Injected into live GL session (${trimmed.length} chars): "${trimmed.slice(0, 80)}"`);
        }
      }

      // 2. Always save the durable agent_notes record.
      //    When injected=false (no active session), this note is queued for session-start delivery.
      const { agentNotes } = await import('@shared/schema');
      await getUserDb().insert(agentNotes).values({
        fromAgent: 'luca',
        toAgent: 'daniela',
        subject: `[RELAY] ${trimmed.slice(0, 200)}`,
        body: trimmed,
        ...(sessionId ? { sessionLabel: `Session: ${sessionId}` } : {}),
      } as any);

      // "stored" is accurate: the agent_notes row is persisted but no automatic
      // delivery path picks it up at session-start yet.  Use injected=true to
      // signal live delivery when that did happen.
      res.json({ stored: true, injected });
    } catch (error: any) {
      console.error('[Luca Chat] relay error:', error);
      res.status(500).json({ error: error.message });
    }
  });

