  // ============================================================================
  // BRAIN SURGERY API (3-WAY COLLABORATION: Editor ↔ Daniela ↔ David)
  // Auth: Accepts either ARCHITECT_SECRET header OR session with admin/developer role
  // ============================================================================
  
  // Helper to check brain surgery auth (secret OR session)
  const checkBrainSurgeryAuth = async (req: any, res: any): Promise<boolean> => {
    // Check for ARCHITECT_SECRET header first (for agent-to-agent calls)
    const secret = req.headers['x-architect-secret'] as string;
    if (secret && validateEditorSecret(secret)) {
      return true;
    }
    
    // Fall back to session-based auth for Command Center access
    if (req.user?.claims?.sub) {
      const userId = getRequestUserId(req);
      const user = await storage.getUser(userId);
      if (user?.role === 'admin' || user?.role === 'developer') {
        return true;
      }
    }
    
    return false;
  };
  
  // Send message from Editor to Daniela (ARCHITECT_SECRET or admin/developer session)
  app.post("/api/brain-surgery/chat", async (req: any, res: Response) => {
    try {
      if (!await checkBrainSurgeryAuth(req, res)) {
        return res.status(401).json({ error: "Unauthorized - requires ARCHITECT_SECRET or admin/developer session" });
      }
      
      const { message, threadId } = req.body;
      if (!message) {
        return res.status(400).json({ error: "Message is required" });
      }
      
      const { brainSurgeryService } = await import('./services/brain-surgery-service');
      // Use enhanced version to track proposals in history for approval/rejection
      const response = await brainSurgeryService.editorToDanielaEnhanced(message, threadId, { includeTeachingContext: true });
      res.json(response);
    } catch (error: any) {
      console.error('[API] Error in brain surgery chat:', error);
      res.status(500).json({ error: error.message });
    }
  });
  
  // Streaming chat endpoint with SSE (Server-Sent Events)
  app.post("/api/brain-surgery/chat/stream", async (req: any, res: Response) => {
    try {
      if (!await checkBrainSurgeryAuth(req, res)) {
        return res.status(401).json({ error: "Unauthorized - requires ARCHITECT_SECRET or admin/developer session" });
      }
      
      const { message, threadId } = req.body;
      if (!message) {
        return res.status(400).json({ error: "Message is required" });
      }
      
      // Generate threadId BEFORE streaming so we can return the correct one
      const actualThreadId = threadId || `brain-surgery-${Date.now()}`;
      
      // Set SSE headers
      res.setHeader('Content-Type', 'text/event-stream');
      res.setHeader('Cache-Control', 'no-cache');
      res.setHeader('Connection', 'keep-alive');
      res.setHeader('X-Accel-Buffering', 'no'); // Disable nginx buffering
      res.flushHeaders();
      
      const { brainSurgeryService } = await import('./services/brain-surgery-service');
      
      // Stream chunks to client - pass the pre-generated threadId
      const result = await brainSurgeryService.editorToDanielaStreaming(
        message,
        actualThreadId,
        (chunk) => {
          // Send chunk as SSE event
          const data = JSON.stringify({
            type: 'chunk',
            index: chunk.index,
            text: chunk.text,
            isComplete: chunk.isComplete,
            isFinal: chunk.isFinal,
          });
          res.write(`data: ${data}\n\n`);
        },
        { includeTeachingContext: true }
      );
      
      // Send final event with proposals and threadId
      const finalData = JSON.stringify({
        type: 'complete',
        id: result.id,
        threadId: actualThreadId,
        content: result.content,
        proposals: result.selfSurgeryProposals || [],
      });
      res.write(`data: ${finalData}\n\n`);
      
      // Close the stream
      res.write('data: [DONE]\n\n');
      res.end();
      
    } catch (error: any) {
      console.error('[API] Error in brain surgery streaming chat:', error);
      // If headers already sent, try to send error via SSE
      if (res.headersSent) {
        const errorData = JSON.stringify({ type: 'error', error: error.message });
        res.write(`data: ${errorData}\n\n`);
        res.end();
      } else {
        res.status(500).json({ error: error.message });
      }
    }
  });
  
