  // Wren: Post message to Express Lane with real-time broadcast
  app.post("/api/wren/message", async (req: any, res: Response) => {
    try {
      // Validate using existing Editor secret (machine-to-machine auth)
      const authHeader = req.headers['x-editor-secret'];
      if (!authHeader || !validateEditorSecret(authHeader as string)) {
        return res.status(401).json({ error: 'Invalid authentication' });
      }

      const { sessionId, content, messageType = 'text' } = req.body;

      if (!sessionId) {
        return res.status(400).json({ error: 'sessionId is required' });
      }
      if (!content) {
        return res.status(400).json({ error: 'content is required' });
      }

      // Verify session exists
      const session = await founderCollabService.getSession(sessionId);
      if (!session) {
        return res.status(404).json({ error: 'Session not found' });
      }

      // Add message and broadcast via WebSocket
      const message = await founderCollabWSBroker.addAndBroadcastMessage(sessionId, {
        role: 'wren',
        messageType,
        content,
      });

      if (!message) {
        return res.status(500).json({ error: 'Failed to add message' });
      }

      // Emit coherence beacon to track Wren's contribution to the Hive
      try {
        await storage.createDanielaBeacon({
          beaconType: 'coherence_check',
          status: 'acknowledged',
          priority: 'low',
          wish: `Wren posted to Express Lane session ${sessionId.substring(0, 8)}`,
          rawContent: content.substring(0, 500),
          // @ts-ignore
          metadata: {
            source: 'wren_api',
            sessionId,
            messageId: message.id,
            timestamp: new Date().toISOString()
          }
        });
        console.log(`[Wren API] Coherence beacon emitted for session ${sessionId}`);
      } catch (beaconError) {
        console.error('[Wren API] Failed to emit beacon:', beaconError);
      }

      console.log(`[Wren API] Message posted to session ${sessionId}, id: ${message.id}`);
      res.json({ 
        success: true, 
        message,
        broadcast: true,
      });
    } catch (error: any) {
      console.error('[Wren API] Post message error:', error);
      res.status(500).json({ error: error.message });
    }
  });

