      const { INTERNAL_BROWSER_TOKEN } = await import('./services/playwright-browser-service');
      if (!token || token !== INTERNAL_BROWSER_TOKEN) {
        return res.status(401).json({ error: 'Invalid browser token' });
      }
      req.session.userId = '49847136';
      req.session.authProvider = 'ai-browser';
