  // Agent-session bootstrap — lets Luca [Replit] start an authenticated session
  // using its dedicated coordination credential.
  app.post("/api/internal/agent-session", async (req: any, res: Response) => {
    try {
      if (!isReplitAgentRequest(req)) {
        return res.status(401).json({ error: 'Invalid agent token' });
      }
      req.session.userId = '49847136';
      req.session.authProvider = 'agent';
      await new Promise<void>((resolve, reject) => req.session.save((err: any) => err ? reject(err) : resolve()));
      res.json({ success: true, message: 'Agent session established' });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  // Trusted Replit-window intake. This route is deliberately agent-token-only:
  // a browser user or local CLI must not be able to mint a provenance receipt
  // for a copy-pasted/manual dump. The collector stores exact bytes privately
  // and signs the resulting receipt; record-window verifies that receipt before
  // canonical capture is allowed.
  app.post("/api/internal/replit-window-intake", requireAgentToken, async (req: any, res: Response) => {
    try {
      const { rawWindowBase64 } = req.body ?? {};
      if (typeof rawWindowBase64 !== 'string' || rawWindowBase64.length === 0) {
        return res.status(400).json({ error: 'rawWindowBase64 is required.' });
      }
      if (rawWindowBase64.length > 2_800_000 || !/^[A-Za-z0-9+/]*={0,2}$/.test(rawWindowBase64)) {
        return res.status(400).json({ error: 'rawWindowBase64 must be a canonical base64 payload within the intake size limit.' });
      }
      const rawBytes = Buffer.from(rawWindowBase64, 'base64');
      if (
        rawBytes.byteLength === 0 ||
        rawBytes.toString('base64') !== rawWindowBase64
      ) {
        return res.status(400).json({ error: 'rawWindowBase64 is not canonical base64 data.' });
      }
      const { createHash, randomUUID, sign } = await import('crypto');
      const { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } = await import('fs');
      const { dirname, join } = await import('path');
      const { WORKSPACE } = await import('./services/transcript-parser');
      const { TRUSTED_REPLIT_WINDOW_RECEIPT_PUBLIC_KEY } = await import('./services/raw-window-audit-service');
      const privateKey = loadTrustedReplitWindowReceiptPrivateKey();
      if (createPublicKey(privateKey).export({ type: 'spki', format: 'pem' }).toString() !== TRUSTED_REPLIT_WINDOW_RECEIPT_PUBLIC_KEY) {
        throw new Error('Trusted Replit-window receipt private key does not match the pinned public verifier.');
      }
      const sourceSha256 = createHash('sha256').update(rawBytes).digest('hex');
      const sourceDir = join(WORKSPACE, '.local', 'raw-window-captures');
      const sourcePath = join(sourceDir, `${sourceSha256}.raw`);
      mkdirSync(dirname(sourcePath), { recursive: true });
      if (existsSync(sourcePath)) {
        if (!readFileSync(sourcePath).equals(rawBytes)) {
          throw new Error(`Raw source SHA-256 collision or prior source corruption at ${sourcePath}`);
        }
      } else {
        const tempPath = `${sourcePath}.tmp-${process.pid}`;
        writeFileSync(tempPath, rawBytes);
        renameSync(tempPath, sourcePath);
      }
      const issuedAt = new Date();
      const expiresAt = new Date(issuedAt.getTime() + 15 * 60 * 1000);
      const unsignedReceipt = {
        version: 1 as const,
        receiptId: randomUUID(),
        intakeRoute: 'trusted-replit-dump-intake' as const,
        sourceSha256,
        sourceBytes: rawBytes.byteLength,
        issuedAt: issuedAt.toISOString(),
        expiresAt: expiresAt.toISOString(),
      };
       const signature = sign(null, Buffer.from([
        unsignedReceipt.version,
        unsignedReceipt.receiptId,
        unsignedReceipt.intakeRoute,
        unsignedReceipt.sourceSha256,
        unsignedReceipt.sourceBytes,
        unsignedReceipt.issuedAt,
        unsignedReceipt.expiresAt,
       ].join('|'), 'utf8'), privateKey).toString('base64url');
      const receipt = { ...unsignedReceipt, signature };
      const receiptPath = join(sourceDir, `${sourceSha256}.replit-receipt.json`);
      const receiptTempPath = `${receiptPath}.tmp-${process.pid}`;
      writeFileSync(receiptTempPath, JSON.stringify(receipt, null, 2) + '\n', 'utf8');
      renameSync(receiptTempPath, receiptPath);
      return res.status(201).json({
        ok: true,
        sourceSha256: receipt.sourceSha256,
        sourceBytes: receipt.sourceBytes,
        receiptId: receipt.receiptId,
        expiresAt: receipt.expiresAt,
      });
    } catch (error: any) {
      console.error('[ReplitWindowIntake] Failed:', error.message);
      return res.status(500).json({ error: 'Trusted Replit-window intake failed.' });
    }
  });

  // Chat-capture turn injection — JSONL replacement (July 27 2026+)
  //
  // Appends a single David or Luca turn to .local/.chat_capture immediately.
  // The autosave worker's fs.watch fires within milliseconds and drains it to
  // conversation_memories automatically — no polling lag, no trigger files.
  //
  // Usage from CodeExecution (x-coordination-token header required):
  //   await fetch('/api/internal/chat-capture-turn', {
  //     method: 'POST',
  //     headers: { 'Content-Type': 'application/json', 'x-coordination-token': process.env.COORDINATION_LUCA_REPLIT_TOKEN },
  //     body: JSON.stringify({ speaker: 'David', text: 'exact verbatim text' }),
  //   });
  //   await fetch('/api/internal/chat-capture-turn', {
  //     method: 'POST',
  //     headers: { 'Content-Type': 'application/json', 'x-coordination-token': process.env.COORDINATION_LUCA_REPLIT_TOKEN },
  //     body: JSON.stringify({ speaker: 'Luca Replit', text: 'exact verbatim text' }),
  //   });
  app.post("/api/internal/chat-capture-turn", async (req: any, res: Response) => {
    try {
      if (!isReplitAgentRequest(req)) {
        return res.status(401).json({ error: 'Invalid agent token' });
      }
      const { speaker, text } = req.body ?? {};
      if (!speaker || typeof speaker !== 'string') {
        return res.status(400).json({ error: 'speaker required (David | Luca | Luca Replit)' });
      }
      if (!text || typeof text !== 'string' || text.trim().length === 0) {
        return res.status(400).json({ error: 'text required and must be non-empty' });
      }
      const { appendChatCaptureTurn } = await import('./services/transcript-parser');
      // appendChatCaptureTurn validates the speaker and throws on invalid values
      appendChatCaptureTurn(speaker.trim(), text);
      // fs.watch on .local/ fires the checkChatCapture() drain automatically — no explicit trigger needed
      console.log(`[ChatCaptureTurn] Appended ${speaker.trim()} turn (${text.length} chars) via HTTP → .chat_capture`);
      return res.json({ ok: true, speaker: speaker.trim(), charLen: text.length });
    } catch (e: any) {
      console.error('[ChatCaptureTurn] Failed:', e.message);
      // Distinguish validation errors (400) from unexpected errors (500)
      if (e.message?.startsWith('appendChatCaptureTurn:')) {
        return res.status(400).json({ error: e.message });
      }
      return res.status(500).json({ error: e.message });
    }
  });

  // Read-only readiness probe for a remote agent. It intentionally exposes
  // neither filesystem paths, tokens, nor dialogue. Historical recovery pauses
  // expose approved source identities and hashes only to these authorized actors.
  // A valid 200 proves the capture workspace is writable AND the in-process
  // drain worker is armed. General /health and /health/readiness intentionally
  // remain separate from this operational capture dimension.
  app.get("/api/internal/canonical-conversation-health", requireCoordinationAuth, async (req: CoordinationAuthenticatedRequest, res: Response) => {
    try {
      if (req.coordinationActor !== 'luca-replit' && req.coordinationActor !== 'luca-claude-code') {
        return res.status(403).json({ error: 'This endpoint requires the luca-replit or luca-claude-code coordination actor' });
      }
      const [
        {
          CHAT_CAPTURE_PATH,
          CHAT_CAPTURE_CURSOR_PATH,
          CHAT_CAPTURE_ACK_CURSOR_PATH,
          loadChatCaptureCursor,
        },
        { inspectCaptureWorkspace },
        { evaluateCanonicalCaptureHealth, getCanonicalCaptureWorkerReadiness },
        fs,
      ] = await Promise.all([
        import('./services/transcript-parser'),
        import('./services/workspace-root'),
        import('./services/canonical-capture-worker-readiness'),
        import('fs'),
      ]);
      const workspace = inspectCaptureWorkspace();
      const captureFilePresent = fs.existsSync(CHAT_CAPTURE_PATH);
      const cursor = loadChatCaptureCursor();
      const acknowledgementCursor = loadChatCaptureCursor(CHAT_CAPTURE_ACK_CURSOR_PATH);
      const captureBytes = captureFilePresent ? fs.statSync(CHAT_CAPTURE_PATH).size : 0;
      const pendingBytes = Math.max(0, captureBytes - cursor.byteOffset);
      const cursorFilePresent = fs.existsSync(CHAT_CAPTURE_CURSOR_PATH);
      const worker = getCanonicalCaptureWorkerReadiness();
      const workspaceReady = workspace.localDirectoryPresent && workspace.localDirectoryWritable;
      const health = evaluateCanonicalCaptureHealth(workspaceReady, worker);
      const { historicalAttributionCaptureHealth } = await import('./services/historical-attribution-status');
      const recoveryHealth = historicalAttributionCaptureHealth(health);

      return res.status(recoveryHealth.status).json({
        ok: recoveryHealth.ok,
        capture: {
          historicalRecovery: recoveryHealth.historicalRecovery,
          worker,
          workspaceSource: workspace.rootSource,
          localDirectoryPresent: workspace.localDirectoryPresent,
          localDirectoryWritable: workspace.localDirectoryWritable,
          captureFilePresent,
          cursorFilePresent,
          cursorByteOffset: cursor.byteOffset,
          acknowledgementCursorByteOffset: acknowledgementCursor.byteOffset,
          pendingBytes,
        },
      });
    } catch (error: any) {
      console.error('[CanonicalConversationHealth] Failed:', error.message);
      return res.status(503).json({
        ok: false,
        error: 'Canonical capture health is unavailable.',
      });
    }
  });

  // Complete, source-attributed exchange intake for both Replit and Claude Code.
  // This is intentionally a write-ahead-log endpoint: accepted means "durably
  // pending in .chat_capture", never "already canonical". The response exposes
  // the per-turn receipt that later becomes acknowledged or failed.
  app.post("/api/internal/canonical-conversation-exchange", requireCoordinationAuth, async (req: CoordinationAuthenticatedRequest, res: Response) => {
    try {
      if (req.coordinationActor !== 'luca-replit' && req.coordinationActor !== 'luca-claude-code') {
        return res.status(403).json({ error: 'This endpoint requires the luca-replit or luca-claude-code coordination actor' });
      }
      const { source, userText, assistantText, turnId } = req.body ?? {};
      if (source !== 'replit' && source !== 'claude-code') {
        return res.status(400).json({ error: 'source must be "replit" or "claude-code"' });
      }
      if (typeof userText !== 'string' || !userText.trim() || typeof assistantText !== 'string' || !assistantText.trim()) {
        return res.status(400).json({ error: 'userText and assistantText must both be non-empty strings' });
      }
      if (typeof turnId !== 'string' || !/^[A-Za-z0-9-]+$/.test(turnId)) {
        return res.status(400).json({ error: 'turnId is required and must contain only letters, digits, and hyphens' });
      }

      const {
        appendCanonicalConversationExchange,
        writeSynchronizedCanonicalCaptureReceipt,
      } = await import('./services/canonical-conversation-capture');
      const capture = appendCanonicalConversationExchange({
        source,
        userText,
        assistantText,
        turnId,
      });
      const receipt = {
        turnId: capture.turnId,
        targetByteOffset: capture.targetByteOffset,
        createdAtMs: Date.now(),
        source,
        status: 'pending' as const,
      };
      writeSynchronizedCanonicalCaptureReceipt(receipt);
      console.log(
        `[CanonicalConversation] ${source} exchange ${capture.turnId} queued ` +
        `(${capture.appendedSpeakers.join('+') || 'retry with no duplicate bytes'}).`,
      );
      return res.status(202).json({
        ok: true,
        acknowledgement: 'pending',
        receipt,
        appendedSpeakers: capture.appendedSpeakers,
        message: 'The exchange is not canonical until the cursor reaches targetByteOffset.',
      });
    } catch (e: any) {
      console.error('[CanonicalConversation] Failed:', e.message);
      // This failure occurred before a new accepted write-ahead record exists.
      // Do not overwrite a valid pending/acknowledged receipt for the same
      // idempotency key; the response is the visible failure for rejected ingress.
      return res.status(e.message?.includes('busy') || e.message?.includes('already') ? 409 : 500).json({ error: e.message });
    }
  });

  // Stage David's task description for atomic David→Luca capture when markTaskComplete fires.
  //
  // Call this from CodeExecution right before markTaskComplete({ task_ref, commit_message }).
  // The endpoint validates the task file exists, then writes the task_ref to
  // .local/.task_ref_pending.  When markTaskComplete writes .commit_message, checkBuildSession()
  // reads the pending file and appends David→Luca as a single synchronous batch — so both turns
  // land in the same .chat_capture drain and produce ONE conversation_memories entry, not two.
  //
  // Usage from CodeExecution (x-coordination-token header required):
  //   await fetch('/api/internal/task-capture-start', {
  //     method: 'POST',
  //     headers: { 'Content-Type': 'application/json', 'x-coordination-token': process.env.COORDINATION_LUCA_REPLIT_TOKEN },
  //     body: JSON.stringify({ task_ref: '1121' }),
  //   });
  //   // immediately call markTaskComplete(...) — the pending file is consumed by checkBuildSession
  app.post("/api/internal/task-capture-start", async (req: any, res: Response) => {
    try {
      if (!isReplitAgentRequest(req)) {
        return res.status(401).json({ error: 'Invalid agent token' });
      }
      const { task_ref } = req.body ?? {};
      if (!task_ref || typeof task_ref !== 'string') {
        return res.status(400).json({ error: 'task_ref required (string task reference number)' });
      }
      const ref = task_ref.trim();
      const { _loadTaskDescriptionText, TASK_REF_PENDING_PATH } = await import('./services/agent-session-autosave');
      const { writeFileSync } = await import('fs');

      // Validate: ensure the task file exists and can produce a David turn before staging.
      const davidText = _loadTaskDescriptionText(ref);
      if (!davidText) {
        return res.status(404).json({ error: `Task file not found or empty for ref=${ref}` });
      }

      // Stage: write task_ref to the companion file.  checkBuildSession() reads this when
      // .commit_message changes and appends David→Luca synchronously (one drain batch).
      writeFileSync(TASK_REF_PENDING_PATH, ref, 'utf-8');
      console.log(`[TaskCaptureStart] Staged task_ref=${ref} → .task_ref_pending (${davidText.length} chars preview)`);
      return res.json({ ok: true, task_ref: ref, charLen: davidText.length, staged: true });
    } catch (e: any) {
      console.error('[TaskCaptureStart] Failed:', e.message);
      return res.status(500).json({ error: e.message });
    }
  });

  // CAP-008: Guardian completion report — called by alden-build-guardian.js (localhost only)
  app.post("/api/team-room/internal/guardian-complete", async (req: any, res: Response) => {
    try {
      const token = req.headers['x-guardian-token'];
      const { GUARDIAN_TOKEN } = await import('./services/alden-build-service');
      if (token !== GUARDIAN_TOKEN) {
        return res.status(403).json({ error: 'Unauthorized' });
      }

      const { roomId, featureName, success, githubSynced, githubError, filesRestored, restoreErrors, error, whatToTest } = req.body;
      if (!roomId) return res.status(400).json({ error: 'roomId required' });

      const { emitNewMessage, emitExpressLane } = await import('./services/team-room-ws-broker');

      let voiceContent: string;
      let expressContent: string;

      if (success) {
        voiceContent = githubSynced
          ? `Verified clean. Server restarted healthy after the changes. Synced to GitHub.${whatToTest ? ` To test: ${whatToTest}` : ''}`
          : `Server restarted healthy — changes are good. GitHub sync failed${githubError ? ` (${githubError})` : ''}, but the code is live on dev.${whatToTest ? ` To test: ${whatToTest}` : ''}`;

        expressContent = [
          `**Build Verified: ${featureName}**`,
          ``,
          `**Server health:** ✓ Clean restart`,
          `**GitHub:** ${githubSynced ? '✓ Synced' : `⚠ Not synced${githubError ? ` — ${githubError}` : ''}`}`,
          whatToTest ? `\n**What to test:** ${whatToTest}` : '',
        ].filter(Boolean).join('\n');
      } else {
        const restoredList = filesRestored?.length > 0 ? filesRestored.join(', ') : 'none';
        voiceContent = `The server didn't restart cleanly — I rolled back the changes. Original files restored: ${restoredList}. Nothing was pushed to GitHub. Let's look at the plan and figure out what went wrong.`;

        expressContent = [
          `**Build Rolled Back: ${featureName}**`,
          ``,
          `**Server health:** ✗ Did not restart after changes`,
          `**Action taken:** Original files restored automatically`,
          `**Files restored:** ${restoredList}`,
          restoreErrors?.length > 0 ? `**Restore errors:** ${restoreErrors.join('; ')}` : '',
          error ? `\n**Error:** ${error}` : '',
          `\n**GitHub:** Not synced (rollback was required)`,
        ].filter(Boolean).join('\n');
      }

      const guardianMsg = await storage.createRoomMessage({
        roomId,
        speaker: 'Alden',
        content: voiceContent,
      });
      emitNewMessage(roomId, guardianMsg);
      emitExpressLane(roomId, [{ participant: 'alden', content: expressContent }]);

      // CAP-009: Post-build screenshot — Alden visually verifies what he built
      if (success) {
        const { aldenPostBuildScreenshot } = await import('./services/playwright-browser-service');
        const screenContext = whatToTest || featureName || 'dashboard';
        aldenPostBuildScreenshot(screenContext, featureName, roomId)
          .catch(err => console.error('[PlaywrightBrowser] Post-build screenshot error:', err));
      }

      console.log(`[Guardian] Report received — ${success ? 'SUCCESS' : 'ROLLBACK'} for "${featureName}" in room ${roomId}`);
      res.json({ ok: true });
    } catch (e: any) {
      console.error('[Guardian] Error processing completion:', e.message);
      res.status(500).json({ error: e.message });
    }
  });

